(window.YSKAR_TEXTE=window.YSKAR_TEXTE||{}).ru={"nav.skip":"Перейти к содержимому","nav.main":"Главная навигация","nav.menu":"Меню","nav.close":"Закрыть","nav.lang":"Язык","nav.tick":"Блок","nav.tick.title":"Самый новый блок. Открывает страницу сети в реальном времени.","cta.join":"Участвовать","nav.g.part":"Участвовать","nav.g.know":"Понять","nav.g.join":"Присоединиться","nav.start":"С чего начать","nav.start.d":"Пять путей входа, у каждого свой первый шаг","nav.mine":"Майнинг","nav.mine.d":"Находи блоки с телефоном, ПК или видеокартой","nav.wallet":"Кошелёк","nav.wallet.d":"Двенадцать слов, которые есть только у тебя","nav.node":"Запустить узел","nav.node.d":"Проверяй каждый блок сам","nav.ysr":"YSR","nav.ysr.d":"21 миллион, и каждый добыт майнингом","nav.chain":"Цепочка","nav.chain.d":"Самостоятельный блокчейн и то, как он сам себя доказывает","nav.network":"Сеть в реальном времени","nav.network.d":"Что цепочка делает прямо сейчас","nav.explorer":"Explorer","nav.explorer.d":"Каждый блок, каждый перевод, каждый адрес","nav.community":"Сообщество","nav.community.d":"Где проект обсуждает и решает","nav.build":"Разработка","nav.build.d":"Открытый код, публичный API, предложения","nav.story":"История и следующие шаги","nav.story.d":"От блока 0 до сегодняшнего дня и что будет дальше","foot.claim":"Честно с блока 0.","foot.sub":"YSKAR — проект сообщества. За ним не стоит ни одна компания, и никому не нужно верить на слово: каждый блок можно проверить.","foot.nav":"Все страницы","foot.whitepaper":"Whitepaper","foot.find":"Где найти YSKAR","foot.imprint":"Правовая информация","foot.privacy":"Конфиденциальность","foot.license":"Открытый исходный код по лицензии MIT","title.home":"Честно с блока 0","title.start":"С чего начать","title.mine":"Майнинг","title.wallet":"YSKAR Wallet","title.node":"Запустить узел","title.ysr":"YSR, монета","title.chain":"Цепочка","title.network":"Сеть в реальном времени","title.explorer":"Explorer","title.build":"Разработка на YSKAR","title.community":"Сообщество","title.story":"История и следующие шаги","ui.copied":"Скопировано","ui.copy":"Копировать","ui.sample":"На экране показаны примерные данные.","dawn.h":"Здесь ещё раннее утро.","dawn.p":"День <span data-live='day'></span>. Первый свет только поднимается над этой сетью. Её облик определяют те, кто здесь сейчас.","dawn.cta2":"Прочитать историю до сегодняшнего дня","dawn.alt":"Тот же фьорд на рассвете: бледное небо над заснеженными горами и неподвижной водой.","nav.guides":"Инструкции","nav.guides.d":"Все способы участия, шаг за шагом","nav.protocol":"Протокол","nav.protocol.d":"Монета, цепочка и кошельки, байт за байтом","nav.paper.d":"Система в том виде, в каком она реализована","title.guides":"Инструкции","title.protocol":"Протокол","title.paper":"Whitepaper","title.imprint":"Правовая информация","title.privacy":"Конфиденциальность","doc.toc":"На этой странице","foot.live":"Цифры на этих страницах читаются в реальном времени из публичного API YSKAR.","foot.stale":"Публичный API YSKAR сейчас не отвечает. Эти страницы показывают цепочку по состоянию на {date} (блок {h}) и сами догонят актуальное состояние.","title.notfound":"Страница не найдена","nf.h":"Такой страницы нет.","nf.p":"Возможно, в ссылке опечатка или страница переехала. Сама цепочка там же, где и была.","nf.home":"На главную страницу","nf.explorer":"Найти что-нибудь в explorer","home.hero.h1":"<span class=\"ln\"><span>Proof,</span></span> <span class=\"ln\"><span>not promise.</span></span>","home.hero.lead":"YSKAR — валюта с собственным блокчейном. Ничего не было роздано заранее: каждый YSR добыт майнингом, и любой может проверить каждый блок. Честно с блока 0.","home.hero.cta2":"Посмотреть цепочку до сегодняшнего дня","home.hero.live":"День {d} · блок {h} · огней на берегу: {n}, по одному на каждый узел, вышедший на связь","home.hero.alt":"Тёмный фьорд между заснеженными горами под звёздным небом. Над ним движутся ленты синего света, а на дальнем берегу горят маленькие тёплые огни.","home.m1":"Всё началось не с обещания. Всё началось с блока.","home.m2":"Ничего не было добыто заранее. Ничего не было роздано. Около 1,07 млн YSR, добытых в первые дни, сожгли, чтобы уравнять фору.","home.m3":"С тех пор новый YSR появляется на свет только одним способом: машина выполняет работу, и любой может это проверить.","walk.start.h":"День <span data-live='day'></span>-й, блок за блоком.","walk.start.p":"Каждый огонёк — настоящий блок, а расстояние между двумя огоньками — время между ними. Прокручивай, чтобы пройти вдоль цепочки. Нажми на огонёк, чтобы открыть его блок.","walk.c0.h":"Всё начинается с одного блока.","walk.c0.p":"Его единственное сообщение — «proof, not promise». Его награда в 875 YSR ушла на адрес, с которого никто не может ничего потратить.","walk.c1.h":"День первый: 46 блоков.","walk.c1.p":"Первый блок после блока 0 появился в 18:03 UTC. К полуночи их было 46: цепочка нашла свой ритм.","walk.c3.h":"Фору сжигают.","walk.c3.p":"1 066 101 YSR, добытых в первые дни, отправлены на адрес, с которого никто не может ничего потратить, чтобы уравнять фору. Всё это в этом блоке.","walk.c4.h":"Сообщество голосует.","walk.c4.p":"Ревизию 6 принимают открыто: общие аккаунты, блокировки по времени, платежи тысяче получателей за один раз. К тому моменту уже действовали три обновления правил.","walk.c5.h":"Ты здесь.","walk.c5.p":"До следующего блока около десяти минут.","walk.c6.h":"Дальше: включается ревизия 6.","walk.c6.p":"Осталось блоков: <span data-live='v6Left'></span>. Каждый узел знает высоту заранее, так что ничего не меняется внезапно.","walk.c6.h.past":"Ревизия 6 действует.","walk.c6.p.past":"С блока 10 000 цепочка знает общие аккаунты, блокировки по времени и пакетные платежи.","walk.c7.h":"Затем заканчивается первая эпоха.","walk.c7.p":"До блока 12 000 каждый блок создаёт 875 YSR, после этого 437,5. Половина всех YSR, которые когда-либо будут существовать, появляется в эту первую эпоху.","walk.c7.h.past":"Первая эпоха завершилась.","walk.c7.p.past":"С блока 12 000 каждый блок создаёт 437,5 YSR. Награда снова уменьшается вдвое каждые 12 000 блоков.","walk.open":"Открыть этот блок","walk.k.block":"Блок {h} · {d}","walk.k.future":"Блок {h} · ещё впереди","home.walk.now":"Блок {h} · день {d}","walk.hud.block":"Блок {h}","walk.hud.ahead":"Блок {h}","walk.hud.planned":"ещё впереди · закреплено в коде","walk.hud.day":"день {n}","walk.tip.block":"Блок {h}","walk.tip.approx":"Подробности загружаются в explorer","walk.tip.solo":"Найден одним майнером","walk.tip.pool":"Найден пулом","walk.tip.tx":"содержал переводы","walk.legend.block":"блок","walk.legend.tx":"блок, в котором были переводы","walk.canvas":"Цепочка, нарисованная как лента огней: по одному огоньку на каждый блок, начиная с блока 0.","home.proof.h":"Не верь нам на слово.","home.proof.p":"Каждый блок несёт собственное доказательство. Твоё устройство может проверить его прямо сейчас: без сервера, без аккаунта, только арифметика.","prove.btn.genesis":"Проверить блок 0 на этом устройстве","prove.btn.tip":"Проверить самый новый блок","prove.label":"Хеш заголовка блока","prove.ok":"Верно. Блок {h} проверен на этом устройстве за {ms} мс.","prove.bad":"Неверно: блок {h} не достигает своей цели.","prove.open":"Открыть блок {h} в explorer","prove.note":"Что только что сделало твоё устройство: дважды пропустило 136 байт заголовка блока через SHA-256. Результат должен быть меньше цели, которую сеть установила для этого блока. Нули в начале показывают, насколько он мал.","home.ways.h":"Три пути входа.","home.ways.p":"Знак YSKAR — три ленты, которые сходятся. Так же устроена и сеть: люди, которые майнят, люди, которые хранят и отправляют, и люди, которые держат узел включённым.","way.mine.h":"Одолжи ей свою машину.","way.mine.p":"Телефон, ПК или видеокарта могут находить блоки. В одиночку или в пуле, который платит тебе прямо в самом блоке и никогда не хранит твои монеты.","way.mine.cta":"Как работает майнинг","way.mine.alt":"Ноутбук на деревянном столе ночью, на нём работает YSKAR Node Core; за ним окно с видом на тёмный фьорд.","way.wallet.h":"Двенадцать слов. Только твои.","way.wallet.p":"Твой кошелёк находится на твоём собственном устройстве. Ни у кого больше нет твоих ключей, в том числе у тех, кто разрабатывает YSKAR.","way.wallet.cta":"Установить кошелёк","way.wallet.alt":"Телефон с открытым YSKAR Wallet лежит на тёмном деревянном столе рядом с блокнотом с двенадцатью рукописными строчками, ручкой и чашкой чая.","way.node.h":"Оставь свет включённым.","way.node.p":"Узел сам проверяет каждый блок, начиная с блока 0. Каждый новый узел делает сеть устойчивее к давлению. Достаточно небольшого компьютера на подоконнике.","way.node.cta":"Запустить узел","way.node.alt":"Небольшой компьютер с одним бирюзовым индикатором на деревянном подоконнике; за окном ночной фьорд и несколько огней на дальнем берегу.","home.ways.more":"Или строй на ней своё. Код открыт, API публичный, а предложения обсуждаются там, где их может прочитать каждый.","home.ways.more.cta":"Для разработчиков","home.early.say":"День {d}. Узлов: {n}. Майнеров: {m}. Пулов: {p}. Переводов: {x}. Ни листинга. Ни цены. Так выглядит самое начало.","home.early.note":"Узлы и майнеры по их собственным сообщениям. Все цифры взяты из публичного API.","home.early.p":"Небольшая сеть, идёт её <span data-live='day'></span>-й день. YSR нигде не торгуется и не имеет цены; листинги готовятся, без дат и без названий. Сегодня есть работающая цепочка, программы, которые можно запустить, и место для тех, кто приходит сейчас.","home.era.h":"Эпоха <span data-live='era'></span>","home.era.p":"В эту эпоху каждый блок создаёт <span data-live='rewardNow'></span> YSR. На блоке <span data-live='halvingHeight'></span> награда уменьшится вдвое, а затем снова будет уменьшаться каждые 12 000 блоков. Половина всех YSR, которые когда-либо будут существовать, появляется в первых 12 000 блоков. График записан в коде; никто не может его сдвинуть.","home.era.now":"Блок <span data-live='height'></span>","home.era.left":"Осталось блоков: <span data-live='halvingLeft'></span>","home.era.cta":"Весь график","home.people.h":"Никакой компании. Только люди.","home.people.p":"YSKAR — проект сообщества, и принадлежит он тем, кто им пользуется. Они майнят, держат узлы, тестируют релизы и открыто решают, что менять: ревизию 6 вынесли на голосование сообщества.","home.people.cta":"Познакомиться с сообществом","home.people.cta2":"Открыть YSKAR Lab","home.people.alt":"Около пятнадцати человек со спины на заснеженном берегу в синий час: каждый держит небольшой фонарь и смотрит на фьорд.","start.h1":"Выбери свой путь входа.","start.lead":"Участие ничего не стоит. Начни с того, что тебе подходит; те же двенадцать слов потом откроют любую дверь.","start.1.h":"Хочу хранить и отправлять YSR","start.1.p":"Установи кошелёк для Android, запиши двенадцать слов на бумаге, покажи свой адрес. Этого достаточно, чтобы получать.","start.1.do":"К кошельку","start.2.h":"Хочу майнить","start.2.p":"Начни с устройства, которое у тебя уже есть: Node Core на ПК, приложение для Android на телефоне, командная строка на риге.","start.2.do":"К майнингу","start.3.h":"Хочу сам проверять цепочку","start.3.p":"Запусти узел. Он проверяет каждый блок с блока 0 и становится ещё одним огоньком на берегу.","start.3.do":"Запустить узел","start.4.h":"Хочу разрабатывать или помогать","start.4.p":"Читай код, обращайся к публичному API, тестируй релизы, приноси предложения в YSKAR Lab.","start.4.do":"Для разработчиков","start.5.h":"Пока хочу просто посмотреть","start.5.p":"Следи за цепочкой в реальном времени, открывай любой блок в explorer, читай обсуждения в канале.","start.5.do":"Сеть в реальном времени","start.safe.h":"Три вещи, которые стоит знать сначала","start.alt.fjord":"Тёмный фьорд под звёздным небом.","mine.h1":"Одолжи ей свою машину.","mine.lead":"Новые YSR появляются только в результате майнинга и больше ниоткуда. Участвовать может телефон, ПК или видеокарта, в одиночку или в пуле.","mine.cta":"Выбери свою конфигурацию","mine.cta2":"Попробовать прямо здесь","mine.try.h":"Майнинг — это угадывание, очень быстрое.","mine.try.p":"Нажми «старт», и это устройство ненадолго подключится. Оно берёт самый новый блок и ищет число, при котором его хеш начинается с достаточного количества нулей: тот же поиск ведёт каждый майнер, только на учебной сложности.","mine.try.go":"Начать угадывать","mine.try.stop":"Стоп","mine.try.again":"Ещё раз","mine.try.tries":"Попытки","mine.try.speed":"Скорость","mine.try.idle":"Пока ничего не найдено. Каждая искра — это серия попыток.","mine.try.found":"Найдено. Попыток: {n}.","mine.try.none":"Попыток: {n}, удача не улыбнулась. Это тоже майнинг. Попробуй ещё раз.","mine.try.real":"Это была тренировка. Настоящая сеть в {x} раз сложнее: при {r} одно это устройство искало бы один настоящий блок примерно {t}. Поэтому майнеры объединяются в пулы.","mine.try.canvas":"Искры для каждой серии попыток; яркая вспышка, когда найдено подходящее число.","mine.setup.h":"Выбери свою конфигурацию","mine.calc.h":"Что могла бы найти твоя машина?","mine.pools.h":"Пулы в реальном времени","wal.h1":"Двенадцать слов. Только твои.","wal.lead":"YSKAR Wallet — приложение для Android для YSR: отправлять, получать, подписывать. Твой ключ создаётся на твоём телефоне и остаётся там.","wal.cta2":"Установка за четыре шага","wal.say":"У кого двенадцать слов, у того и средства. Запиши их на бумаге. Никто из YSKAR никогда не попросит их у тебя.","node.h1":"Оставь свет включённым.","node.lead":"Full node сам проверяет каждый блок, начиная с блока 0, и передаёт его дальше. Он никого не спрашивает, что считать правдой. Каждый узел, который так делает, делает сеть устойчивее к давлению.","node.cta":"Скачать Node Core","node.cta2":"Из командной строки","node.say":"Каждый огонёк на этом берегу — узел, вышедший на связь. Сейчас их {n}. Твой был бы под номером {k}.","node.core.h":"Node Core: узел, кошелёк и майнер в одном окне.","node.core.p":"Установи его, и твой компьютер сам проверит цепочку. Node Core также хранит твой кошелёк, майнит на процессоре или видеокарте, может вести пул и подписывает сообщения. Версия 1.1.0 для Windows 10 и 11 и для 64-битного Linux.","node.dl.win":"Установщик для Windows","node.dl.deb":"Пакет для Linux (.deb)","node.dl.app":"AppImage для Linux","node.dl.get":"Скачать","node.dl.all":"Все файлы и контрольные суммы","node.dl.rel":"Релиз на GitHub","node.why.h":"Что меняет ещё один узел","node.w1.p":"Твой узел пересчитывает работу, подписи и каждый баланс, начиная с блока 0. Блок, нарушающий правило, отклоняется, кто бы его ни прислал.","node.w2.h":"Он держит сеть","node.w2.p":"Каждый узел передаёт блоки и переводы другим. Чем их больше и чем шире они разбросаны, тем меньше сеть зависит от одной машины.","node.w3.h":"Ему нужно немного","node.w3.p":"Из командной строки узел работает на Linux, Windows и macOS, даже на Raspberry Pi. Node Core, настольное приложение, работает на Windows и 64-битном Linux.","coin.h1":"21 миллион. И каждый добыт майнингом.","coin.lead":"YSR — монета цепочки YSKAR. Их никогда не будет больше 21 000 000. Ничего не было добыто заранее или распределено: новый YSR появляется только по одной причине — найден блок.","coin.alt":"Монета YSR: толстый диск из синего стекла с приподнятым краем и рельефным знаком YSKAR.","coin.alt.flat":"Монета YSR: тёмный диск с синим кольцом и знаком YSKAR.","coin.bar.mined":"добыто на сегодня","coin.bar.burned":"из них сожжено или недоступно для траты","coin.bar.open":"ещё предстоит добыть","coin.eras.h":"Награда уменьшается вдвое каждые 12 000 блоков.","coin.eras.p":"Каждый столбец — одна эпоха; он показывает, сколько YSR в ней создаётся. Одна только первая эпоха создаёт половину всего. Последний новый YSR появится в блоке 443 999; после этого майнеры получают только комиссии.","coin.eras.era":"Эпоха {n}","coin.eras.now":"сейчас","coin.eras.rest":"Значения в YSR. 9+ означает все последующие эпохи вместе.","coin.burn.h":"Фору сожгли.","coin.burn.cta":"Посмотреть в блоке 3 974","chain.h1":"Собственная цепочка.","chain.lead":"YSKAR не работает поверх чужой сети. У него свои блоки, своя одноранговая сеть и свои правила, и каждый блок он доказывает работой, которую может проверить любой.","chain.how.h":"Один блок, три шага.","chain.why.h":"Почему важна собственная цепочка","chain.y1.h":"Её правила принадлежат ей","chain.y1.p":"Комиссии, время блоков и обновления определяются здесь, теми, кто поддерживает YSKAR, а не в чьей-то чужой сети.","chain.y2.h":"Ничего не нужно принимать на веру","chain.y2.p":"Каждый блок вплоть до блока 0 может пересчитать любой: открытой программой, на обычном компьютере.","chain.y3.h":"Изменения приходят открыто","chain.y3.p":"Изменение правил записывается в код вместе с блоком, с которого оно начинает действовать. Каждый узел знает о нём заранее. Ревизию 6 вынесли на голосование сообщества.","chain.deep.h":"Для любопытных: как всё устроено в деталях","chain.deep.p":"Дальше страница становится технической. Всё, что ниже, взято из кода консенсуса и из самой цепочки.","netp.lead":"Что цепочка делает прямо сейчас, по данным публичного API. Здесь ничего не оценивается вручную.","bld.h1":"Строй на ней.","bld.lead":"Весь YSKAR открыт: узел, кошельки, майнеры, explorer и этот сайт — под лицензией MIT. Публичный API отвечает без ключа.","bld.cta":"Попробовать API","bld.cta2":"Код на GitHub","bld.1.h":"Прочитать всё","bld.1.p":"Протокол описан, код консенсуса достаточно короткий, чтобы его прочитать, а каждая цифра на этом сайте взята из этого кода или из цепочки.","bld.2.h":"Спросить цепочку","bld.2.p":"Блоки, переводы, адреса, комиссии, пулы и эмиссия по обычному HTTP. Без ключа, без регистрации, открыто для любого сайта.","bld.3.h":"Изменить","bld.3.p":"Предложения проходят через YSKAR Lab, публично, от первой идеи до релиза. Вход — через твой кошелёк.","comm.h1":"Никакой компании. Только люди.","comm.lead":"YSKAR — проект сообщества, и принадлежит он тем, кто им пользуется. Здесь они обсуждают, тестируют и решают.","comm.ch.h":"Где всех найти","comm.do.h":"Что ты можешь сделать. Ни на что из этого не нужно разрешение.","comm.lab.h":"Как предложение становится релизом","comm.safe.h":"Береги себя и свои средства","comm.ann":"Bitcointalk","story.h1":"Шаги, а не даты.","story.lead":"Откуда появился YSKAR, что работает сегодня и что будет дальше. Никто здесь не обещает сроков: изменения вступают в силу на определённом блоке, а не в день по календарю.","story.why.h":"Зачем существует YSKAR","story.why.say":"Цель — валюта, которой люди могут пользоваться в повседневной жизни. Сначала прочный фундамент. Короткая волна ажиотажа в планы не входит.","story.why.p":"YSKAR принадлежит тем, кто им пользуется. Твои YSR лежат на адресе, который открывают только твои двенадцать слов. Никому не нужно доверять: каждый блок вплоть до блока 0 может проверить любой. Новые YSR появляются из майнинга, а не из обещаний.","story.run.h":"Работает сегодня","story.fix.h":"Закреплено высотой блока","story.plan.h":"Запланировано, без даты","story.walk":"Пройти вдоль цепочки от блока 0","coin.field.alt":"Поле огней для всех 21 миллиона YSR: уже добытые горят, сожжённые тлеют, как угли, остальные тёмные.","coin.field.burned":"сожжено","coin.f0.h":"21 000 000. Больше не будет никогда.","coin.f0.p":"Каждый огонёк обозначает <span data-field-unit></span> YSR, в том порядке, в каком они появляются. Это всё, что когда-либо будет существовать.","coin.f1.p":"Столько существует сегодня, это <span data-live='mintedPct'></span> от общего числа. Каждый из них вышел из блока, который кто-то нашёл.","coin.f2.p":"Около 1,07 млн YSR, добытых в первые дни, сожгли, чтобы уравнять фору. Они ушли на адрес, с которого никто не может ничего потратить, и исчезли навсегда.","coin.f3.h":"Половина всего появляется вначале.","coin.f3.p":"Первые 12 000 блоков создают 10,5 млн YSR: половину всего, что когда-либо будет. Цепочка сейчас на блоке <span data-live='height'></span>.","coin.f4.h":"Потом награда уменьшается вдвое, снова и снова.","coin.f4.p":"Каждые 12 000 блоков награда сокращается вдвое. Последний новый YSR появится в блоке 443 999. После этого майнеры получают только комиссии.","coin.noprice.say":"Сегодня у YSR нет цены. Он нигде не торгуется. Зато у него есть цепочка, которую может проверить любой.","wal.phone.alt":"Телефон, на котором один за другим показаны настоящие экраны YSKAR Wallet.","wal.s1.h":"Твой баланс, и ничего лишнего.","wal.s3.h":"Одна история для всего.","wal.s3.p":"Платежи, награды за блоки и доли пула собраны в одном месте. Суммы точны до восьмого знака после запятой.","wal.s5.h":"Имена вместо адресов.","wal.s5.p":"Сохрани контакт один раз, и все платежи с этим человеком окажутся в одной ленте.","pay.alt":"Множество маленьких огоньков мерцает, собирается в одну яркую точку, которая становится блоком, а от блока лучи расходятся к каждому адресу, которому он платит.","pay.0.h":"Все угадывают одновременно.","pay.0.p":"Прямо сейчас вся сеть работает со скоростью около <span data-live='hashrate'></span>: миллиарды чисел в секунду, и все ищут один и тот же блок.","pay.1.h":"Одно число подходит.","pay.1.p":"Примерно каждые десять минут какая-то машина находит подходящее число. Это новый блок, и поиск начинается заново.","pay.2.h":"Блок платит всем, кто помогал.","pay.2.p":"В пуле награда делится по работе, которую выполнил каждый майнер, и выплачивается прямо в самом блоке. Число адресов, которым разом заплатил последний блок пула: <span id='pay-n'></span>.","pay.3.h":"Без аккаунта. Без порога выплаты. Без хранения у третьих лиц.","calcx.a":"Моя машина выдаёт","calcx.b":"и я майню","poolsx.last":"из последних блоков","poolsx.fee":"комиссия","poolsx.seats":"мест занято","poolsx.rate":"заявлено","shore.on":"Зажечь ещё один","shore.off":"Снова погасить","shore.note.on":"Номер {k} горит только на твоём экране. Он пойдёт в счёт, когда твой узел заработает.","node.check.h":"От блока 0 до сегодняшнего дня, никого не спрашивая.","comm.vote.say":"25 октября 2026 года сообщество проголосовало о том, когда начнётся ревизия 6. Выбран блок 10 000.","comm.vote.cta":"Что приносит ревизия 6","log.k":"Каждый блок до","log.cap":"Каждая строка — один день с 9 сентября 2026 года (UTC), каждая отметка — один блок в своё время суток. Тёплые отметки содержали переводы. Нажми на отметку, чтобы открыть блок.","log.cap.n":"Каждая строка охватывает {d} дней с 9 сентября 2026 года (UTC), каждая отметка — один блок. Тёплые отметки содержали переводы. Нажми на отметку, чтобы открыть блок.","log.cap.n.few":"Каждая строка охватывает {d} дня с 9 сентября 2026 года (UTC), каждая отметка — один блок. Тёплые отметки содержали переводы. Нажми на отметку, чтобы открыть блок.","log.alt":"Бортовой журнал цепочки: каждый блок с блока 0 в виде отметки, одна строка на день.","comm.say":"День {d}. Узлов, которые хранят цепочку: {n}. Майнеров, которые её продолжают: {m}. Пулов, которые делят работу: {p}. Никого не назначали. Они пришли сами.","road.start.k":"25 окт. 2026","road.start":"Голосование","road.end.k":"Блок 10 000","road.end":"Начинается ревизия 6","road.now":"Блок {h} · сейчас","road.left":"Осталось блоков: {n}. При нынешнем темпе это {eta}.","road.done":"Ревизия 6 действует с блока 10 000.","road.need":"До этого блока узлам нужен актуальный релиз.","road.need.done":"Узлы со старым релизом больше не следуют за цепочкой.","coin.turn":"Перевернуть","coin.turn.back":"Перевернуть обратно","coin.back.k":"Блок 0","coin.back.d":"9 сентября 2026 года","netp.say":"Блок {h}, найден {a}. Над следующим работает {r}. Наблюдающих узлов: {n}.","start.jump":"Пять путей","start.guides":"Каждый путь объяснён шаг за шагом","story.road.h":"Цепочка до сегодняшнего дня и то, что уже определено","story.road.p":"Семь отметок вдоль цепочки. У тех, что позади, есть дата. У тех, что впереди, только номер блока, потому что больше код ничего не знает.","story.road.live":"Посмотреть последние блоки","miles.left":"осталось блоков: {n}","forge.hash":"SHA-256, применённый дважды","forge.target":"не должен превышать цель","forge.ok":"Верно: пересчитано на этом устройстве.","forge.nodes":"{n} узлов на связи","forge.nodes.few":"{n} узла на связи","forge.nodes.1":"{n} узел на связи","forge.paid":"{r} на {n} адресов","forge.paid.few":"{r} на {n} адреса","forge.paid.1":"{r} на {n} адрес","forge.before":"Блоков перед ним: {n}, с теми же интервалами, с какими их нашли: {m} мин","forge.alt":"136 байт заголовка самого нового блока. Nonce меняется, пока хеш не окажется ниже цели; затем узлы проверяют его, блок занимает своё место в конце цепочки и выплачивает награду.","term.note.live":"Ответ публичного API от {d}.","term.note.snap":"Ответ от {d}. API сейчас не отвечает; страница сама спросит ещё раз.","term.more":"Показать все строки ({n})","term.less":"Показать меньше строк","term.alt":"Запрос к публичному API и ответ на него","agol.sec":"{n} секунд назад","agol.sec.few":"{n} секунды назад","agol.sec.1":"{n} секунду назад","agol.min":"{n} минут назад","agol.min.few":"{n} минуты назад","agol.min.1":"{n} минуту назад","agol.hours":"{n} часов назад","agol.hours.few":"{n} часа назад","agol.hours.1":"{n} час назад","agol.days":"{n} дней назад","agol.days.few":"{n} дня назад","agol.days.1":"{n} день назад","netp.k":"Сеть в реальном времени","netp.k.snap":"Сеть на {date}","netp.say.snap":"Последним был блок {h}. Над следующим работало {r}. Наблюдавших узлов: {n}.","netp.lead.snap":"Последнее состояние, которое получила эта страница. Публичный API сейчас не отвечает; страница сама спросит ещё раз.","ex.h1":"Каждый блок открыт для всех.","ex.lead":"Найди блок, перевод или адрес. Твой браузер пересчитывает Proof of Work каждого блока, который показывает.","ex.q.ph":"Блок, хеш или адрес","pulse.tip.h":"Последние {n} ч","pulse.next":"Идёт майнинг блока {h}. С последнего блока прошло {t}.","pulse.around.h":"Вокруг блока {h}","pulse.around.n":"{n} блоков за эти {k} ч","pulse.around.n.few":"{n} блока за эти {k} ч","pulse.now":"сейчас","pulse.by":"Нашёл: {who}","pulse.alt":"Блоки на временной шкале. Каждый огонёк — один блок; расстояние между двумя огоньками — время между ними.","ex.row.tx":"{n} переводов","ex.row.tx.few":"{n} перевода","ex.row.tx.1":"{n} перевод","ex.row.tx0":"переводов нет","ex.proof.h":"Proof of Work","ex.proof.p":"Майнер перебирает два счётчика в заголовке, nonce и extranonce, пока хеш всех 136 байт не окажется ниже цели. Твой браузер только что повторил этот расчёт.","proof.pick":"Выбери поле, чтобы увидеть, что в нём.","pulse.around.n.1":"{n} блок за эти {k} ч","ex.tx.batch":"Пакетный платёж","ex.tx.script":"Расход со скрипт-аккаунта","ex.txv.status":"Статус","ex.txv.waiting":"Ожидает блока","ex.txv.sumPending":"Отправлено, но пока не попало в блок.","ex.txv.expected":"Ожидается в блоке {h}, примерно через {min} мин, если не появится ничего с более высокой комиссией.","ex.txv.unknownWhen":"Дальше в очереди, чем достаёт прогноз.","ex.addr.waiting":"Ожидает","ex.addr.older":"Загрузить более ранние операции","ex.next.tag":"в работе","ex.next.h":"Что уже известно наверняка","ex.next.reward":"Награда","ex.next.pending":"Ожидающие транзакции","ex.next.empty":"Мемпул пуст, поэтому пока в этом блоке только coinbase.","ex.next.some":"Ожидающие платежи попадут в этот блок, насколько поместятся.","ex.next.who":"Кто его найдёт, пока неизвестно.","ex.fill":"{p}% занято","ex.fill.of":"{n} из {max} транзакций","ex.queue.h":"Очередь","ex.queue.row":"{n} tx · от {fee} · ~{min} мин","ex.queue.none":"Ничего не ждёт — следующий блок заберёт всё.","ex.queue.more":"Всего транзакций: {n}, блоков: {b}.","ex.queue.note":"Ожидаемый порядок по комиссии за байт, если ничего нового не придёт. Комиссия указана для перевода без заметки.","ex.check.h":"Проверка в твоём браузере","ex.check.note":"Эти проверки выполняются здесь, а не на сервере.","ex.check.ser":"Сериализация","ex.check.hash":"Хеш пересчитан","ex.check.pow":"Proof of Work","ex.check.link":"Связь цепочки","ex.check.ok":"верно","ex.check.bad":"НЕВЕРНО","ex.check.open":"открыто","ex.check.p":"Заголовок собирается заново из полей, хешируется дважды, сверяется с записанной сложностью, проверяется связь с предыдущим блоком. Эти проверки выполняются здесь, а не на сервере. Какие блоки показаны, определяет зеркало сервера; оно сверяется с full node, и расхождение будет показано здесь. Зелёная точка на блоке значит: проверено здесь.","ex.f.achieved":"Достигнуто","ex.f.time":"Время блока","ex.f.time.s":"после предыдущего блока","ex.verdict.ok":"{n} блоков проверены здесь","ex.verdict.ok.few":"{n} блока проверены здесь","ex.verdict.ok.1":"{n} блок проверен здесь","ex.verdict.bad":"Одна из проверок не пройдена","ex.verified":"проверено здесь","ex.mirror.fork":"Зеркало показывает на высоте {h} другой блок, чем full node. Список ниже может относиться к другой ветке.","ex.mirror.behind":"Зеркало отстаёт от full node (блоков: {n}). Самых новых блоков ниже нет.","ex.mirror.behind.1":"Зеркало отстаёт от full node (блоков: {n}). Самых новых блоков ниже нет.","lv.an.apk.akku":"Некоторые устройства всё равно закрывают фоновые приложения, чтобы экономить заряд. Если майнинг останавливается сам, установи для приложения расход батареи «Без ограничений» (Настройки → Приложения → YSKAR Wallet → Батарея).","lv.an.apk.dienst":"Начиная с версии 1.0.9 считает отдельная служба приложения. Майнинг продолжается, когда ты выходишь из приложения или блокируешь экран. Пока он идёт, Android показывает уведомление с твоим хешрейтом; кнопка «Остановить майнинг» останавливает его прямо оттуда.","lv.an.apk.hintergrund":"Майнинг в фоне","lv.an.apk.inst":"Установка","lv.an.apk.knopf":"Скачать последнюю версию","lv.an.apk.m1":"Открой вкладку «Майнинг» и пролистай до раздела «Управление».","lv.an.apk.m2":"Выбери режим: Solo или Pool. В режиме Pool приложение предлагает открытый пул; по кнопке «Сменить» ты увидишь все пулы с числом майнеров, мощностью, найденными блоками и комиссией. Заполненный пул выбрать нельзя.","lv.an.apk.m3":"Настрой «Worker» и «Нагрузка». Worker — это ядра процессора, которые считают; нагрузка задаёт, насколько сильно они загружены (от 25 до 100 %).","lv.an.apk.m4":"Нажми «Начать майнинг». Если Android спросит про уведомления, разреши их: так видно, что майнинг идёт, и там же его можно остановить.","lv.an.apk.name":"На телефоне это приложение называется «YSKAR Wallet». Это другое приложение, чем новый YSKAR Wallet без майнинга; оба можно установить рядом, и твои 12 слов работают в обоих.","lv.an.apk.pruefen":"Проверка загрузки (необязательно)","lv.an.apk.pruefenText":"В каждом релизе есть ещё файл с окончанием <code>.sha256</code>. В нём записана контрольная сумма APK. Если контрольная сумма твоего файла совпадает, это ровно тот файл, который опубликовали мы.","lv.an.apk.s1":"Открой страницу загрузки на телефоне и нажми на файл <code>yskar-wallet-….apk</code>.","lv.an.apk.s2":"Android спросит, можно ли устанавливать приложения из этого источника (например, из твоего браузера). Нажми «Настройки» и разреши установку для этого источника.","lv.an.apk.s3":"Вернись назад и нажми «Установить». Google Play Protect может показать предупреждение — для приложений не из Play Store это нормально.","lv.an.apk.s4":"Открой приложение, создай кошелёк или восстанови существующий по 12 словам.","lv.an.apk.start":"Запуск майнинга","lv.an.apk.text":"Android-приложение продолжает майнить в фоне, даже при заблокированном экране, и показывает майнинг в виджете на главном экране. Поскольку Google Play не допускает майнинг на устройстве, эта версия доступна напрямую у нас.","lv.an.apk.tipp":"Наша рекомендация: все Worker, нагрузка 25 %, в пуле. Так меньше расход батареи и нагрев, а в пуле небольшие суммы приходят регулярнее. «Калибровать устройство» подберёт лучшее число Worker для твоего телефона.","lv.an.apk.titel":"Android-приложение с майнингом","lv.an.apk.update":"Обновление приложения","lv.an.apk.updateText":"Когда выходит новая версия, приложение показывает сообщение при открытии. Нажми «Загрузить»: приложение скачает обновление, затем Android спросит, установить ли его. Кошелёк сохраняется. Проверить вручную можно в приложении: Настройки → Приложение → Обновления.","lv.an.apk.w1":"Нажми и удерживай свободное место на главном экране, выбери «Виджеты» и перетащи «YSKAR Wallet» на экран.","lv.an.apk.w2":"Когда майнинг идёт, виджет показывает, сколько заработано за эту сессию, а также хешрейт, время и принятые shares. Кнопка «Стоп» останавливает майнинг прямо с главного экрана. Когда майнинг остановлен, видны текущий блок, хешрейт сети и награда за блок.","lv.an.apk.w3":"«Заработано за эту сессию» считает награды за блоки и выплаты пула, зачисленные на твой адрес с момента запуска; значение меняется, когда найден новый блок. Светлую или тёмную тему выбирают в приложении: Настройки → Приложение → Виджет. Виджет в таком виде доступен с версии 1.1.0.","lv.an.apk.widget":"Виджет на главном экране","lv.an.etikett":"Инструкции","lv.an.ex.p1":"Ищи по высоте блока, хешу или адресу.","lv.an.ex.p2":"У каждого блока видно, кто его нашёл: имя, пул или solo-адрес.","lv.an.ex.p3":"Введи свой адрес, чтобы проверить свои выплаты.","lv.an.ex.text":"<a href=\"/explorer\">Explorer</a> показывает каждый блок, каждый перевод и каждый адрес. Он заново собирает заголовок каждого блока в твоём браузере, хеширует его и проверяет Proof of Work и цепочку. Переводы, подписи и балансы проверяют full node: запусти свой, и тебе не придётся никому верить.","lv.an.ex.titel":"Explorer","lv.an.gr.aus":"Как пул выплачивает","lv.an.gr.aus1":"Сам блок напрямую выплачивает всем участникам. Оператор пула никогда не держит твои деньги, и порога выплаты нет.","lv.an.gr.aus2":"Считается работа за последнее время, измеренная в шарах (shares). Если ты только начал, твоя доля в первом блоке будет соответственно небольшой.","lv.an.gr.gebuehr":"Оператор может брать комиссию от 0 до 5 %. Она указана в списке пулов.","lv.an.gr.hinweis":"Никто не может обещать тебе доход. Как часто ты что-то получаешь, зависит от твоей вычислительной мощности, от мощности сети и от случая.","lv.an.gr.p1":"YSKAR — это собственный блокчейн. Новый блок находят примерно каждые 10 минут. Кто его нашёл, получает награду — сейчас 875 YSR — прямо на свой адрес.","lv.an.gr.p2":"Чтобы найти блок, твоё устройство перебирает числа (двойной SHA-256). Чем больше у тебя вычислительной мощности, тем выше шансы. Сложность (difficulty) подстраивается под мощность всей сети.","lv.an.gr.plaetze":"Один блок может выплатить не более чем 64 адресам, поэтому в пуле не больше 64 мест (63, если пул берёт комиссию). Место засчитывается, только пока ты майнишь: новое устройство занимает его на 2 минуты на пробу и сохраняет, регулярно отправляя шары. Места тех, кто перестал майнить, снова освобождаются.","lv.an.gr.pool":"<strong>Пул:</strong> многие ищут вместе. Когда пул находит блок, награда делится по вложенной работе. Суммы меньше, зато приходят регулярнее.","lv.an.gr.solo":"<strong>Solo:</strong> ты ищешь один. Если найдёшь блок, вся награда твоя. Это может занять много времени.","lv.an.gr.sp":"Solo или пул","lv.an.gr.titel":"Как работает майнинг","lv.an.hi.a1":"Android закрывает приложение, чтобы экономить заряд. Установи для YSKAR Wallet расход батареи «Без ограничений» (Настройки → Приложения → YSKAR Wallet → Батарея).","lv.an.hi.a2":"В пуле не больше 64 мест. Место освобождается сразу, когда майнер останавливается, и не позже чем через 20 минут, если майнер перестаёт выходить на связь, так что попытка позже может сработать. Иначе выбери другой пул или майни solo. Если у твоего адреса уже есть место, другие устройства всё равно могут присоединиться.","lv.an.hi.a3":"Узел пока не нашёл ни одного другого узла. Проверь подключение к интернету и то, разрешил ли ты Node Core в запросе брандмауэра Windows. Затем немного подожди.","lv.an.hi.a4":"Узел ещё синхронизируется. Майнинг начнётся, когда в обзоре появится «In sync».","lv.an.hi.a5":"Для майнинга на видеокарте нужна карта NVIDIA, AMD или Intel с актуальным драйвером. Установи актуальный драйвер производителя и перезапусти Node Core. Перед майнингом каждая карта проходит самопроверку; карта, не прошедшая её, не используется.","lv.an.hi.a6":"Восстанови кошелёк по тем же 12 словам в том же порядке. Другой набор слов — это другой кошелёк.","lv.an.hi.a7":"Вопросы задавай в <a href=\"https://t.me/+GxAmtTMeG1w1M2Yy\">чате сообщества в Telegram</a>. Об ошибках сообщай на <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHub</a>. Никогда не сообщай свои 12 слов: администраторы никогда не пишут тебе первыми.","lv.an.hi.f1":"Майнинг на телефоне останавливается сам","lv.an.hi.f2":"«Pool full»","lv.an.hi.f3":"Node Core: «No peer connected yet»","lv.an.hi.f4":"Node Core: майнинг не запускается","lv.an.hi.f5":"Видеокарта не найдена","lv.an.hi.f6":"На новом устройстве нет моего баланса","lv.an.hi.f7":"Что-то другое","lv.an.hi.titel":"Если что-то не работает","lv.an.mini.hinweis":"Совет: во вкладке «Майнинг» можно выбрать между solo и пулом. В пуле ты чаще получаешь небольшие суммы; solo — реже, но сразу целые блоки.","lv.an.mini.s1":"Открой <a href=\"https://t.me/YSKAR_bot\">@YSKAR_bot</a> в Telegram и запусти приложение.","lv.an.mini.s2":"Нажми «Создать кошелёк». Приложение покажет 12 слов: запиши их на бумаге по порядку.","lv.an.mini.s3":"Подтверди несколько слов и выбери PIN.","lv.an.mini.s4":"Открой вкладку «Майнинг» и нажми «Начать майнинг». Пока идут вычисления, держи приложение открытым.","lv.an.mini.text":"Самый быстрый способ начать. Mini App работает внутри Telegram, устанавливать ничего не нужно.","lv.an.mini.titel":"Telegram Mini App","lv.an.nc.e1":"<strong>Узел:</strong> папка данных, порты и seed уже заполнены. Значения по умолчанию подходят большинству — просто нажми «Continue».","lv.an.nc.e2":"<strong>Кошелёк:</strong> создай новый кошелёк и запиши 12 слов или перенеси существующий кошелёк по своим 12 словам. Выбери пароль не короче 8 символов; он шифрует слова на этом ПК. Кошелёк можно настроить и позже.","lv.an.nc.e3":"<strong>Запуск:</strong> нажми «Start node».","lv.an.nc.einst":"Настройки","lv.an.nc.erst":"Первый запуск","lv.an.nc.firewall":"При первом запуске Windows спросит, можно ли Node Core выходить в сеть. Разреши, иначе узел не сможет найти другие узлы.","lv.an.nc.firewallLinux":"В Linux такого запроса нет. Если включён файрвол (например, ufw), открой порт 8646 — иначе другие узлы не смогут подключиться к твоему. Твои собственные подключения работают в любом случае.","lv.an.nc.i1":"Скачай установщик и запусти его.","lv.an.nc.i2":"Windows покажет «Система Windows защитила ваш компьютер», потому что установщик не подписан. Выбери «Подробнее», затем «Выполнить в любом случае».","lv.an.nc.i3":"Следуй указаниям установщика. После этого Node Core запустится.","lv.an.nc.inst":"Установка в Windows","lv.an.nc.l1":"<strong>Ubuntu, Debian, Linux Mint:</strong> скачай файл <code>.deb</code> и установи его в терминале. Затем запусти «YSKAR Node Core» из меню приложений.","lv.an.nc.l2":"<strong>Другие дистрибутивы:</strong> скачай AppImage, сделай его исполняемым и запусти. Для AppImage нужен FUSE 2 (в Ubuntu — пакет <code>libfuse2</code>).","lv.an.nc.l3":"Node Core для Linux работает на 64-битных ПК (x86-64) с рабочим столом. ARM-компьютеры, например Raspberry Pi, не поддерживаются.","lv.an.nc.linux":"Установка в Linux","lv.an.nc.m1":"Выбери цель: Solo или Pool. В режиме Pool выбери пул из списка или введи адрес в поле «Your own pool address» и проверь его.","lv.an.nc.m2":"«Reward goes to»: твой собственный кошелёк или другой адрес.","lv.an.nc.m3":"Выбери устройство: процессор, видеокарта или оба. Задай число ядер и нагрузку на ядро.","lv.an.nc.m4":"Только solo: при желании введи имя, которое будет указано в найденных тобой блоках. Оно публично и остаётся навсегда.","lv.an.nc.m5":"Нажми «Start mining».","lv.an.nc.mining":"Майнинг","lv.an.nc.poolHinweis":"Если пул больше тебя не принимает, майнинг останавливается и сообщает причину. Он никогда не продолжает молча в режиме solo.","lv.an.nc.port":"Нужно ли открывать порт?","lv.an.nc.portText":"Нет. И без этого твой узел сам подключается к другим узлам. Если открыть порт 8646 на роутере, другие узлы тоже смогут достучаться до твоего. Это помогает сети, но необязательно.","lv.an.nc.pruefen":"Чтобы убедиться, что это именно тот файл, который мы опубликовали, сравни его контрольную сумму с файлом <code>.sha256</code> из релиза. В PowerShell:","lv.an.nc.pruefenLinux":"В Linux:","lv.an.nc.s1":"<strong>Запуск вместе с Windows</strong> (в Linux: «Запускать при входе в систему»): Node Core запускается без окна, когда ты входишь в систему.","lv.an.nc.s2":"<strong>Продолжать работу после закрытия:</strong> окно сворачивается в область уведомлений рядом с часами, узел продолжает работать.","lv.an.nc.s3":"<strong>Возобновлять майнинг после запуска:</strong> майнинг продолжается с последними настройками, как только узел синхронизируется.","lv.an.nc.s4":"<strong>Обновления:</strong> Node Core сообщает, когда доступна новая версия. Само по себе ничего не устанавливается.","lv.an.nc.sig":"Подпись и YSKAR Lab","lv.an.nc.sigText":"С версии 1.1.0 «Подписать» в кошельке подписывает текст твоим адресом, например чтобы доказать, что адрес принадлежит тебе; «Проверить» проверяет подписанное сообщение другого человека. На <a href=\"https://lab.yskar.app\">lab.yskar.app</a> кнопка «Войти через кошелёк» открывает Node Core: он показывает сайт, твой адрес и срок действия запроса и подписывает только после подтверждения паролем. Подпись не может переместить YSR.","lv.an.nc.sync":"Первая синхронизация","lv.an.nc.syncText":"При первом запуске Node Core загружает весь блокчейн и проверяет каждый блок. Это может занять некоторое время; ход загрузки показан в обзоре. Майнинг начнётся только тогда, когда узел догонит сеть.","lv.an.nc.text":"Node Core — это программа YSKAR для Windows и Linux: свой узел с кошельком и майнингом в одном окне. Она загружает блокчейн на твой ПК и сама проверяет каждый блок.","lv.an.nc.titel":"Node Core для Windows и Linux","lv.an.nc.update":"Обновление","lv.an.nc.updateText":"Скачай новый установщик, закрой Node Core — в том числе в области уведомлений — и запусти установщик. Твой кошелёк и блокчейн сохранятся.","lv.an.nc.v1":"Windows 10 или 11 (64 бита) либо Linux (64 бита, x86-64) и подключение к интернету","lv.an.nc.v2":"Место на диске для блокчейна. Он пока небольшой и растёт с каждым блоком.","lv.an.nc.v3":"Для майнинга на видеокарте: карта NVIDIA, AMD или Intel с актуальным драйвером. Без неё считает процессор.","lv.an.nc.vor":"Что тебе нужно","lv.an.nc.w1":"<strong>Отправить:</strong> введи получателя и сумму, проверь, подтверди паролем. Пароль запрашивается перед каждым переводом.","lv.an.nc.w2":"<strong>Получить:</strong> покажи свой адрес или его QR-код.","lv.an.nc.w3":"<strong>Контакты:</strong> имена вместо адресов, хранятся только на этом ПК.","lv.an.nc.w4":"<strong>Блокировка:</strong> кошелёк блокируется сам после 10 минут без действий и каждый раз, когда блокируется Windows. Время можно изменить в настройках.","lv.an.nc.wallet":"Кошелёк","lv.an.node.s1":"1. Сборка","lv.an.node.s2":"2. Запуск и подключение к сети","lv.an.node.s2Text":"Узел подключается к другому узлу (seed), загружает цепочку и проверяет её блок за блоком. Другие узлы смогут достучаться до твоего через порт 8646, если открыть его на роутере; это необязательно. С параметром --no-upstream твой узел передаёт блоки только другим узлам, а не веб-серверу проекта.","lv.an.node.s3":"3. Майнинг на собственном узле","lv.an.node.s4":"4. Запуск пула (необязательно)","lv.an.node.s4Fuss":"--pool-fee задаётся в базисных пунктах: 100 = 1,00 %, максимум 500.","lv.an.node.s4Mehr":"Что нужно пулу, чтобы приложение и другие майнеры могли до него достучаться, описано в разделе <a href=\"/anleitungen#pool\">Запуск пула</a>.","lv.an.node.s4Text":"Любой узел может стать пулом, без регистрации. Сам блок выплачивает всем участникам; ты никогда не держишь чужих средств.","lv.an.node.s5":"5. Как служба на Raspberry Pi","lv.an.node.s5Text":"Чтобы узел сам запускался после перезагрузки, настрой его как службу systemd. Готовые файлы и инструкция лежат в репозитории в <a href=\"https://github.com/dabitlex/YSKAR/tree/main/deploy\"><code>deploy/</code></a>.","lv.an.node.text":"Full node загружает цепочку и сам проверяет каждый блок — Proof of Work, подписи, балансы. Нужен Node.js 22.13 или новее; узел отлично работает на Raspberry Pi.","lv.an.node.titel":"Запуск full node","lv.an.node.win":"В Windows используй npm.cmd вместо npm.","lv.an.pc.s1":"1. Установи Node.js","lv.an.pc.s1Text":"Майнеру нужен Node.js 20 или новее. Скачай LTS-версию с <a href=\"https://nodejs.org\">nodejs.org</a> и установи её. В Windows после этого открой новое окно командной строки.","lv.an.pc.s2":"2. Получи майнер","lv.an.pc.s2Text":"Больше ничего устанавливать не нужно. Самотест проверяет, правильно ли твой компьютер вычисляет хеши.","lv.an.pc.s3":"3. Начни майнить","lv.an.pc.s3Text":"Замени адрес на свой адрес YSKAR (он начинается с ysr1). С пулом:","lv.an.pc.s4":"4. Видеокарта (необязательно)","lv.an.pc.s4Text":"С видеокартой добавь <code>--gpu</code>. Для этого нужна GPU-программа: <code>yskar-cuda</code> для карт NVIDIA, <code>yskar-opencl</code> для карт AMD и Intel. Майнер берёт первую, которая находит карту; <code>--gpu-api opencl</code> выбирает программу для AMD и Intel, даже если стоит карта NVIDIA. Для Linux обе прикреплены к каждому релизу Node Core (<code>yskar-cuda-…-linux-x86_64</code>, <code>yskar-opencl-…-linux-x86_64</code>); в Windows собери их, как описано в репозитории в <code>node-core/gpu</code>.","lv.an.pc.s5":"5. Майнинг-фермы с HiveOS","lv.an.pc.s5Text":"Для майнинг-ферм с HiveOS есть готовый пакет: этот майнер с GPU-программой, по одному майнеру на каждую карту NVIDIA, AMD или Intel, без комиссии. Он прикреплён к каждому выпуску Node Core как <code>yskar-hiveos-….tar.gz</code>. Как настроить flight sheet, описано в <a href=\"https://github.com/dabitlex/YSKAR/blob/main/hiveos/README.md\">hiveos/README.md</a>.","lv.an.pc.solo":"Solo вместо пула: убери --mode pool. Целые блоки, но реже.","lv.an.pc.text":"Майнер работает на Windows, macOS и Linux. Ему нужен только адрес — ни приватного ключа, ни кошелька, ни регистрации. Его можно спокойно запускать на любом компьютере.","lv.an.pc.titel":"Майнер для ПК","lv.an.pool.beitritt":"Как майнеры присоединяются","lv.an.pool.beitrittText":"В приложении выбери «Pool» и введи адрес своего пула в поле «Свой адрес»; в Node Core — в поле «Your own pool address». С майнером для ПК:","lv.an.pool.caddy":"Конфигурация для Caddy. Замени имя на своё; оно должно заранее указывать на твой компьютер.","lv.an.pool.g1":"<strong>Имя:</strong> от 3 до 32 простых символов. Оно записывается в каждый блок твоего пула и остаётся там навсегда.","lv.an.pool.g2":"<strong>Комиссия:</strong> от 0 до 5 %. В команде <code>--pool-fee</code> задаётся в базисных пунктах: 100 = 1 %. Если берёшь комиссию, нужно указать адрес, на который она идёт.","lv.an.pool.g3":"<strong>Места:</strong> не более 64 адресов, с комиссией — 63: один получатель — это ты.","lv.an.pool.g4":"<strong>Никаких чужих денег:</strong> блок выплачивает всем напрямую. Ты никогда не держишь средства своих майнеров.","lv.an.pool.h1":"Открой «Run a pool», задай имя, комиссию и число мест и включи пул.","lv.an.pool.h2":"В разделе Mining выбери «Pool». Твой собственный пул стоит в списке первым.","lv.an.pool.h3":"Для других ПК включи «Devices in your home network». Они подключаются по адресу <code>http://&lt;адрес этого ПК&gt;:8645</code>.","lv.an.pool.heim":"В домашней сети с Node Core","lv.an.pool.heimText":"Пул в Node Core отвечает только твоему собственному ПК и твоей собственной сети. Из интернета он так недоступен.","lv.an.pool.k1":"Кто майнит с тобой","lv.an.pool.k2":"Что тебе нужно","lv.an.pool.liste":"Как попасть в список пулов","lv.an.pool.listeText":"Приложение и Node Core показывают поддерживаемый вручную список пулов. Чтобы попасть в него, твой пул должен быть доступен по HTTPS и отвечать на <code>/api/v2/pool</code>. Попроси об этом на <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHub</a>. Список — это не проверка и не рекомендация: число майнеров, мощность и комиссию пул сообщает сам.","lv.an.pool.n1":"<strong>Узел, который работает постоянно.</strong> Лучше всего подходит узел из командной строки на Raspberry Pi или на сервере; см. <a href=\"/anleitungen#fullnode\">Запуск full node</a>.","lv.an.pool.n2":"<strong>Имя</strong>, по которому она доступна: собственный домен или бесплатное имя DynDNS.","lv.an.pool.n3":"<strong>HTTPS с действительным сертификатом.</strong> Telegram и браузеры ничего не загружают без шифрования. Без HTTPS ни один телефон не достучится до твоего пула.","lv.an.pool.n4":"<strong>Веб-сервер перед узлом</strong>, который получает сертификат и передаёт запросы узлу, например Caddy.","lv.an.pool.n5":"<strong>Открытый порт 443.</strong> Для узла дома это означает проброс порта на роутере.","lv.an.pool.netz":"Для приложения, Mini App и майнеров из интернета","lv.an.pool.netzText":"Вот что тебе нужно:","lv.an.pool.o1":"<strong>Дома:</strong> никаких дополнительных расходов. Но твой IP-адрес становится общеизвестным, нужен проброс порта, а нагрузка ложится на твоё подключение.","lv.an.pool.o2":"<strong>Арендованный сервер:</strong> твой домашний IP-адрес остаётся в стороне, и на сервере не хранятся ключи — только адрес для комиссии. Сначала прочитай условия провайдера: многие запрещают майнинг и всё, что с ним связано. Получи разрешение в письменном виде.","lv.an.pool.ort":"Дома или на арендованном сервере?","lv.an.pool.r1a":"Ты и устройства в твоей домашней сети","lv.an.pool.r1b":"Node Core с включённой функцией «Run a pool»","lv.an.pool.r2a":"Майнеры для ПК из интернета","lv.an.pool.r2b":"Узел, который работает постоянно и доступен извне","lv.an.pool.r3a":"Приложение и Mini App","lv.an.pool.r3b":"Дополнительно HTTPS: имя (домен или DynDNS) и сертификат","lv.an.pool.regeln":"Правила для каждого пула","lv.an.pool.start":"Запусти узел как пул. Он слушает только на самом компьютере; перед ним стоит веб-сервер.","lv.an.pool.test":"Проверь снаружи. Если в ответе есть имя твоего пула и число мест, пул доступен.","lv.an.pool.text":"Пул в YSKAR — это не сервис с учётными записями. Это узел, который делит награду за свои блоки. Запустить его может любой, без регистрации. Что тебе понадобится, зависит от того, кто должен майнить вместе с тобой.","lv.an.pool.titel":"Запуск пула","lv.an.si.p1":"<strong>Твои 12 слов — это твой кошелёк.</strong> Никогда не вводи их на сайтах и никому не отправляй. Никто из YSKAR не попросит их у тебя.","lv.an.si.p2":"<strong>Скачивай только с yskar.app и из проекта YSKAR на GitHub.</strong> Если хочешь быть уверен, сравни контрольную сумму.","lv.an.si.p3":"<strong>Обновляй свои программы.</strong> При объявленном изменении правил устаревший узел либо останавливается на этом блоке, либо продолжает работать, не проверяя новое правило, — и то и другое повод обновиться вовремя.","lv.an.si.p4":"<strong>Если ты запускаешь узел:</strong> другие узлы видят твой IP-адрес, как в любой peer-to-peer-сети. Проброс порта тебе не нужен. Если не хочешь, чтобы твой адрес был виден, используй VPN.","lv.an.si.p5":"<strong>Node Core:</strong> кошелёк и интерфейс доступны только с твоего собственного ПК.","lv.an.si.titel":"Безопасность","lv.an.text":"Всё объяснено шаг за шагом: майнинг на телефоне и на ПК, твой кошелёк, собственный узел и собственный пул.","lv.an.titel":"Шаг за шагом","lv.an.tocLabel":"На этой странице","lv.an.ue.k1":"Способ","lv.an.ue.k2":"Для чего подходит","lv.an.ue.k3":"Что нужно","lv.an.ue.r1a":"Telegram Mini App","lv.an.ue.r1b":"Попробовать, прямо сейчас","lv.an.ue.r1c":"Telegram","lv.an.ue.r2a":"Android-приложение","lv.an.ue.r2b":"Майнинг в фоне на телефоне","lv.an.ue.r2c":"Телефон на Android","lv.an.ue.r3a":"Node Core","lv.an.ue.r3b":"Свой узел с кошельком и майнингом на ПК, в том числе на видеокарте","lv.an.ue.r3c":"Windows 10/11 или Linux (64 бита)","lv.an.ue.r4a":"Майнер для ПК","lv.an.ue.r4b":"Майнинг из командной строки","lv.an.ue.r4c":"Windows, macOS или Linux с Node.js","lv.an.ue.r5a":"Full node","lv.an.ue.r5b":"Узел или пул на Raspberry Pi или на сервере","lv.an.ue.r5c":"Linux, Windows или macOS с Node.js 22.13 или новее","lv.an.ue.text":"Участвовать можно пятью способами. Все они используют один и тот же кошелёк: с твоими 12 словами ты везде получаешь доступ к одному и тому же балансу.","lv.an.ue.titel":"Какой способ тебе подходит?","lv.an.w.empfangen":"Получение","lv.an.w.empfangenText":"Покажи свой адрес или его QR-код. В код можно добавить сумму и заметку; тогда отправителю останется только подтвердить. Свой адрес можно давать кому угодно, а свои 12 слов — никому.","lv.an.w.kontakte":"Контакты и история","lv.an.w.kontakteText":"Контакты дают адресам имена; они хранятся только на твоём устройстве. История показывает каждый платёж; доходы от майнинга за один день собраны в одну строку, которую можно раскрыть вплоть до отдельного блока.","lv.an.w.s1":"Получатель: вставь адрес, отсканируй QR-код или выбери контакт. Адрес YSKAR начинается с ysr1.","lv.an.w.s2":"Сумма и, при желании, заметка до 32 байт — это 32 простые латинские буквы; кириллицей помещается примерно вдвое меньше. Заметка открыто хранится в блокчейне.","lv.an.w.s3":"Комиссия: её предлагает приложение. Когда сеть не загружена, минимальной комиссии хватит для следующего блока.","lv.an.w.s4":"Проверка: приложение показывает адрес полностью и сообщает, отправлял ли ты на него раньше. Подтверди с помощью PIN или отпечатка пальца.","lv.an.w.senden":"Отправка","lv.an.w.warn":"Отправленный платёж нельзя вернуть. Проверь весь адрес, прежде чем подтверждать.","lv.an.wallet.p1":"Запиши слова на бумаге в правильном порядке. Никаких скриншотов, никакого облака.","lv.an.wallet.p2":"Храни листок в надёжном месте. Если потеряешь телефон, слова восстановят всё.","lv.an.wallet.p3":"PIN защищает только приложение на этом устройстве. Слова он не заменяет.","lv.an.wallet.p4":"Чтобы перейти на новое устройство, выбери «У меня уже есть двенадцать слов» и введи их.","lv.an.wallet.text":"Твой кошелёк создаётся на твоём устройстве из 12 слов. Эти слова — твой ключ: у кого они есть, тот получает доступ к средствам — на любом устройстве, в любом приложении YSKAR.","lv.an.wallet.titel":"Твой кошелёк","lv.fuss.datenschutz":"Конфиденциальность","lv.fuss.impressum":"Правовая информация","lv.hood.f2.k":"Сложность","lv.nc.appimage":"AppImage для других дистрибутивов Linux","lv.nc.bildNotiz":"Пример экрана — числа условные.","lv.nc.knopfLinux":"Скачать для Linux (.deb)","lv.nc.knopfWin":"Скачать для Windows","lv.nc.mehr":"Контрольная сумма и заметки о версии","lv.nc.system":"Windows 10 или 11 (64 бита)","lv.nc.systemLinux":"Linux 64 бита · Ubuntu, Debian, Mint","lv.pr.block.alt":"136-байтовый заголовок блока и его десять полей","lv.pr.block.merkle":"Один хеш по всем транзакциям в блоке. Его изменит один-единственный изменённый байт в любом переводе.","lv.pr.block.nonce":"Число, которое перебирают майнеры. Первые 128 байт для задания не меняются, поэтому каждая попытка требует всего двух шагов сжатия SHA-256.","lv.pr.block.prev":"Хеш предыдущего блока. Он связывает цепочку: изменение старого блока изменило бы все последующие хеши.","lv.pr.block.state":"Один хеш по всем аккаунтам (баланс и nonce) после этого блока. Каждый узел вычисляет его сам и сравнивает.","lv.pr.block.text":"Каждый блок начинается ровно со 136 байт. Его хеш — двойной SHA-256 от этих байт, и он не должен превышать цель, которую задаёт сложность.","lv.pr.block.titel":"Устройство заголовка блока","lv.pr.db.ablauf":"Срок действия","lv.pr.db.ablaufWert":"необязательно, по высоте блока","lv.pr.db.adresse":"Адрес","lv.pr.db.adresseWert":"ysr1…, 42 символа; общие аккаунты с V6: ysr1p…, 63 символа (bech32m)","lv.pr.db.blockzeitWert":"600 секунд (цель)","lv.pr.db.diffWert":"LWMA по 45 блокам, на каждом блоке","lv.pr.db.einheit":"Наименьшая единица","lv.pr.db.gebuehr":"Комиссии получает","lv.pr.db.gebuehrWert":"майнер блока","lv.pr.db.kette":"Цепочка","lv.pr.db.knoten":"Full node","lv.pr.db.knotenWert":"каждая хранит и проверяет всю цепочку","lv.pr.db.konsens":"Консенсус","lv.pr.db.konsensWert":"Proof of Work, SHA-256d","lv.pr.db.memo":"Заметка","lv.pr.db.memoWert":"до 32 байт","lv.pr.db.minGeb":"Минимальная комиссия (консенсус)","lv.pr.db.minGebWert":"1 единица за байт","lv.pr.db.modell":"Модель","lv.pr.db.modellWert":"аккаунты с балансом и nonce","lv.pr.db.muenze":"Монета","lv.pr.db.name":"Название · тикер","lv.pr.db.netz":"Сеть","lv.pr.db.notfall":"Аварийное правило","lv.pr.db.notfallWert":"легче после 30 мин без блока","lv.pr.db.nullkonto":"Адрес сжигания","lv.pr.db.pfad":"Вывод ключей","lv.pr.db.pool":"Пулы","lv.pr.db.poolWert":"выплата из блока, комиссия 0–5 %","lv.pr.db.relay":"Минимальная комиссия для передачи","lv.pr.db.relayWert":"10 единиц за байт","lv.pr.db.sig":"Подписи","lv.pr.db.staub":"Минимальная сумма отправки","lv.pr.db.staubWert":"100 единиц","lv.pr.db.transfer":"Размер перевода","lv.pr.db.transferWert":"от 168 до 200 байт","lv.pr.db.tx":"Транзакций на блок","lv.pr.db.txWert":"до 2000","lv.pr.db.vorab":"Премайн · распределение","lv.pr.db.vorabWert":"нет","lv.pr.db.wahl":"Выбор цепочки","lv.pr.db.wahlWert":"наибольшая накопленная работа","lv.pr.db.wallet":"Кошельки и аккаунты","lv.pr.db.worte":"Seed-слова","lv.pr.db.worteWert":"BIP39, 12 или 24 слова","lv.pr.etikett":"Протокол в деталях","lv.pr.gen.belohnung":"Награда","lv.pr.gen.belohnungWert":"875 YSR, потратить нельзя","lv.pr.gen.text":"Первый блок цепочки. Его coinbase содержит короткое сообщение, а награда ушла на адрес, с которого никто не может ничего потратить.","lv.pr.gen.titel":"Блок 0","lv.pr.gen.zeit":"Временная метка","lv.pr.pruefen":"Проверь блок 0 или последний блок сам, прямо в браузере.","lv.pr.text":"Всё, что ниже, зафиксировано в коде консенсуса и одинаково для каждого узла. Ничто не зависит от сервера, компании или настройки.","lv.pr.titel1":"YSKAR и YSR,","lv.pr.titel2":"байт за байтом.","lv.pr.tx.alt":"Поля перевода","lv.pr.tx.p1":"Подпись охватывает и chain ID, поэтому перевод, подписанный для YSKAR, недействителен в любой другой сети.","lv.pr.tx.p2":"Nonce считает переводы, отправленные аккаунтом. Один и тот же перевод никогда не может быть применён дважды.","lv.pr.tx.p3":"Необязательная высота истечения позволяет переводу утратить силу, если к этому моменту он не попал в блок.","lv.pr.tx.text":"Перевод перемещает YSR с одного аккаунта на другой. Он занимает 168 байт плюс необязательную заметку.","lv.pr.tx.titel":"Устройство перевода","lv.recht.nurDeutsch":"Эта страница на немецком языке, как того требует законодательство Германии.","lv.supply.aera.fuss":"Награды считаются в целых базовых единицах (0,00000001 YSR), поэтому при каждом халвинге остаток отбрасывается: всего будет выпущено 20 999 999,99832 YSR, чуть меньше максимума.","lv.supply.aera.k1":"Эпоха","lv.supply.aera.k2":"Блоки","lv.supply.aera.k3":"Награда за блок","lv.supply.aera.k4":"Выпущено за эпоху","lv.supply.aera.k5":"Всего после эпохи","lv.supply.aera.text":"Эпоха длится 12 000 блоков, около 83 дней. В каждой эпохе награда вдвое меньше, чем в предыдущей. Начиная с блока 444 000 новые YSR не создаются, и майнеры получают только комиссии.","lv.supply.aera.titel":"Эмиссия по эпохам","lv.wallet.warnung":"<strong>У кого 12 слов, у того и средства.</strong> Никому их не сообщай. Никто из YSKAR никогда не попросит их у тебя.","lv.wpseite.drucken":"Печать / сохранить в PDF","lv.wpseite.toc":"Содержание","lv.wpseite.untertitel":"Блокчейн на Proof of Work, который каждый может майнить и каждый может проверить.","lv.zahlen.blockzeit":"Время блока","lv.wpseite.nurDeEn":"Whitepaper пока доступен на английском и немецком.","unit.min":"{n} мин","unit.hours":"{n} ч","unit.days":"{n} дн.","ago.sec":"{n} с назад","ago.min":"{n} мин назад","ago.hours":"{n} ч назад","ago.days":"{n} дн. назад","eta.around":"примерно через {d}, около {date}","v6.active":"Действует с блока 10 000","v6.pending":"осталось блоков: {n}","mode.live":"Напрямую из цепочки","mode.snapshot":"Состояние на {date}","mode.history":"История до блока {h}","mode.liveShort":"Доступно","mode.snapshotShort":"Последнее известное состояние","dur.years":"{n} лет","dur.years.1":"{n} год","dur.years.few":"{n} года","dur.years.frac":"{n} года","dur.years.big":"{n} лет","dur.days":"{n} дней","dur.days.1":"{n} день","dur.days.few":"{n} дня","dur.hours":"{n} часов","dur.hours.1":"{n} час","dur.hours.few":"{n} часа","dur.min":"{n} минут","dur.min.1":"{n} минуту","dur.min.few":"{n} минуты","dur.sec":"{n} секунд","dur.sec.few":"{n} секунды","dur.sec.1":"{n} секунду","rm.run.p":"Выпущено и используется. Каждый пункт ведёт туда, где это можно проверить.","rm.run.1.h":"Основная сеть","rm.run.1.p":"Блоки с 9 сент. 2026. Цепочка сейчас на блоке","rm.run.1.l":"Сеть в реальном времени","rm.run.2.h":"Ревизии консенсуса со 2-й по 5-ю","rm.run.2.p":"Действуют с блоков 2 000, 4 000, 6 000 и 7 000.","rm.run.2.l":"Что изменила каждая из них","rm.run.3.p":"Full node, кошелёк, майнинг на CPU и GPU и работа пула для Windows и Linux.","rm.run.3.l":"Скачать","rm.run.4.p":"Кошелёк для Android: отправлять, получать, подписывать. Готов к ревизии 6.","rm.run.4.l":"О кошельке","rm.run.5.h":"Три публичных пула","rm.run.5.p":"YSKAR MAIN, Gozero и ODW.Serv. Программа пула открыта; запустить свой может любой.","rm.run.5.l":"Пулы в реальном времени","rm.run.6.h":"Explorer и публичный API","rm.run.6.p":"Каждый блок, перевод и адрес, в браузере и по HTTP.","rm.run.6.l":"Открыть explorer","rm.run.7.p":"Предложения, обсуждение и статус открыты для всех. Вход — через твой кошелёк.","rm.fix.p":"Эти изменения записаны в коде консенсуса. Они вступают в силу на определённом блоке, а не в определённую дату: когда наступит этот блок, зависит от того, как быстро находятся блоки.","rm.fix.blocks":"блоков","rm.fix.1.at":"Блок 10 000","rm.fix.1.h":"Ревизия 6","rm.fix.1.p":"Общие аккаунты с числом ключей до 16, блокировки по времени и хеш-блокировки, пакетные переводы числу получателей до 1 000 и место для 5 000 транзакций в блоке. Хардфорк, утверждённый после голосования сообщества 25 окт. 2026. До этого блока на узлах должен стоять актуальный релиз.","rm.fix.1.l":"Что меняется на блоке 10 000","rm.fix.2.at":"Блок 12 000","rm.fix.2.h":"Первый халвинг","rm.fix.2.p":"Награда за блок снижается с 875 до 437,5 YSR. Затем она уменьшается вдвое каждые 12 000 блоков.","rm.fix.2.l":"Весь график","rm.fix.after":"Последний новый YSR будет создан в блоке 443 999. После этого майнеры получают только комиссии.","rm.plan.p":"Намерения, а не обещания. Здесь ни у чего нет даты, и порядок может измениться.","rm.plan.1.h":"Свопы и мгновенные платежи","rm.plan.1.p":"Ревизия 6 приносит в цепочку базовые элементы: хеш-блокировки и блокировки по времени. Функции кошелька, которые используют их для свопов и платежей в реальном времени, появятся позже.","rm.plan.2.h":"Stratum для майнинг-ригов","rm.plan.2.p":"Сегодня майнеры и пулы общаются по собственному HTTP-протоколу YSKAR. Stratum запланирован на время, когда сеть вырастет.","rm.plan.3.h":"Майнинг на общие аккаунты","rm.plan.3.p":"Ревизия 6 не может выплатить награду за блок на общий аккаунт. Спецификация оставляет это ревизии 7.","rm.plan.4.h":"Кошелёк со своим узлом","rm.plan.4.p":"Сегодня YSKAR Wallet читает балансы с публичного сервера. В планах: направить его на full node, который ты держишь сам.","rm.plan.5.h":"YSKAR Wallet в Play Store","rm.plan.5.p":"Сегодня кошелёк распространяется как APK из GitHub Releases.","rm.plan.6.h":"Публичная тестовая сеть и решения сообщества","rm.plan.6.p":"Следующие этапы YSKAR Lab: пробовать изменения до того, как они попадут в основную сеть, и вместе решать их судьбу.","rm.plan.7.h":"Листинги на биржах","rm.plan.7.p":"Готовятся, без дат и без названий. Сегодня у YSR нет ни цены, ни рынка, и никому не стоит майнить в расчёте на то, что это изменится.","rm.how.p":"Предложения пишутся, обсуждаются и отслеживаются публично в YSKAR Lab. Изменение правил консенсуса требует спецификации и попадает в основную сеть только на высоте блока, которую каждый узел знает заранее.","com.ch.p":"Объявления сначала появляются в Telegram-канале. Всё остальное — для вопросов и обсуждений.","com.ch.1":"Релизы и новости.","com.ch.2":"Вопросы и обсуждения с другими майнерами и пользователями.","com.ch.3":"Короткие новости от @yskar_official.","com.ch.4":"Тема с объявлениями.","com.ch.5":"Исходный код, релизы и задачи.","com.ch.6":"Предложения, от первой идеи до релиза.","com.do.1.h":"Запустить full node","com.do.1.p":"Каждый узел, который сам проверяет блоки, делает сеть менее зависимой от одного сервера.","com.do.2.h":"Майнить, в одиночку или в пуле","com.do.2.p":"Когда хешрейт распределён между многими майнерами и несколькими пулами, цепочкой труднее управлять.","com.do.3.h":"Запустить пул","com.do.3.p":"Программа пула входит в репозиторий и платит майнерам прямо в блоке. Ещё один независимый пул распределяет хешрейт ещё шире.","com.do.4.h":"Тестировать и сообщать","com.do.4.p":"Попробуй релиз и заведи задачу о том, что сломалось. Напиши, что ты увидел и как это воспроизвести.","com.do.5.h":"Предлагать и обсуждать","com.do.5.p":"Принеси идею в YSKAR Lab или улучши чужую в комментариях.","com.lab.p":"Каждое предложение проходит одни и те же шесть этапов, и каждый видит, на каком оно сейчас.","com.lab.s1":"Идея","com.lab.s1.d":"Поделись тем, что задумал.","com.lab.s2":"Обсуждение","com.lab.s2.d":"Улучшайте её вместе в комментариях.","com.lab.s3":"Черновик","com.lab.s3.d":"Текст, дизайн, спецификация или код.","com.lab.s4":"В планах","com.lab.s4.d":"Назначено на один из ближайших релизов, с обоснованием.","com.lab.s5":"В тестовой сети","com.lab.s5.d":"Попробуй до того, как это попадёт в основную сеть.","com.lab.s6":"Выпущено","com.lab.s6.d":"Выпущено, со ссылкой на релиз.","com.lab.k1":"Автор проводит предложение через первые три этапа.","com.lab.k2":"Начиная с этапа «В планах» этап назначает команда, всегда с обоснованием.","com.lab.open":"Открыть YSKAR Lab","com.safe.1.h":"Твои 12 слов остаются у тебя","com.safe.1.p":"Никто из YSKAR никогда не попросит твои 12 слов, PIN-код или файл кошелька. Тот, кто просит, пытается забрать твои монеты.","com.safe.2.h":"Скачивай из первоисточника","com.safe.2.p":"Бери программы из релизов на GitHub, на которые ссылается этот сайт, и перед установкой сверяй отпечаток сертификата кошелька.","com.safe.3.h":"Никаких обещаний","com.safe.3.p":"Сегодня у YSR нет ни цены, ни рынка, и он не торгуется ни на одной бирже. Ничто здесь не обещает, что это изменится.","com.channel":"Канал в Telegram","com.chat":"Чат сообщества","wallet.dl":"Скачай APK","wallet.meta":"Версия 2.0.0, для Android 7 и новее. Открытый исходный код по лицензии MIT. На английском и немецком языках.","wallet.feat.p":"Без рекламы, без слежки и без аккаунта где бы то ни было. Приложение общается с сетью YSKAR и больше ни с чем.","wallet.f1.h":"Твой ключ остаётся у тебя","wallet.f1.p":"Кошелёк создаётся на твоём телефоне. 12 слов восстановления возвращают его на любом устройстве. Они хранятся в защищённом хранилище Android в зашифрованном твоим PIN-кодом виде и никогда не попадают в облачные резервные копии.","wallet.f2.h":"Отправлять осознанно","wallet.f2.p":"Введи адрес, выбери контакт или отсканируй QR-код. Перед отправкой ты ещё раз видишь получателя, сумму и сетевую комиссию, а затем проводишь по экрану, чтобы подтвердить. Перевод нельзя отменить.","wallet.f3.h":"Получать и запрашивать","wallet.f3.p":"Покажи свой QR-код или адрес. Если хочешь, запроси конкретную сумму: отправителю останется только подтвердить.","wallet.f5.h":"Подписывать и входить","wallet.f5.p":"Подтверди подписанным сообщением, что адрес принадлежит тебе, и проверяй чужие подписи. Входи в YSKAR Lab по QR-коду. Подпись не может переместить YSR.","wallet.f6.h":"Надёжно закрыт","wallet.f6.p":"PIN-код и отпечаток пальца, автоматическая блокировка через выбранное тобой время, запрет скриншотов, пока на экране 12 слов, и собственная клавиатура приложения, так что ничего из введённого не проходит через клавиатурное приложение телефона.","wallet.inst.h":"Установка за четыре шага","wallet.inst.p":"Кошелёк распространяется в виде APK через релизы на GitHub. Обновления устанавливаются поверх предыдущей версии, а твой кошелёк остаётся на устройстве.","wallet.inst.1":"Открой <a class='ext' href='https://github.com/dabitlex/YSKAR--WALLET/releases/latest' target='_blank' rel='noopener'>последний релиз</a> на своём телефоне с Android и скачай файл <code>yskar-wallet-…apk</code>.","wallet.inst.2":"Открой файл. Разреши установку из этого источника, когда Android спросит.","wallet.inst.3":"Нажми «Create wallet» и запиши 12 слов на бумаге, по порядку.","wallet.inst.4":"Выбери PIN-код. Чтобы перенести уже существующий кошелёк, вместо этого введи его 12 слов.","wallet.verify.h":"Проверь, что файл подлинный","wallet.verify.p":"Каждый релиз подписан одним и тем же ключом. Это отпечаток SHA-256 его сертификата. Если отпечаток скачанного файла отличается, не устанавливай его.","wallet.oth.h":"Другие места для твоих YSR","wallet.oth.p":"Все приложения YSKAR используют одни и те же 12 слов. С ними ты везде попадаешь к одному и тому же балансу.","wallet.oth.1.h":"YSKAR Wallet","wallet.oth.1.p":"Android. Отправка, получение, подпись. Не майнит.","wallet.oth.2.h":"Node Core","wallet.oth.2.p":"Windows и Linux. Кошелёк внутри твоего собственного full node, с майнингом и подписью сообщений. <a href='/mining#setup'>Скачать Node Core</a>","wallet.oth.3.h":"Android-приложение с майнингом","wallet.oth.3.p":"Кошелёк и майнинг на телефоне, с виджетом на главном экране и уведомлениями.","wallet.oth.4.h":"Telegram Mini App","wallet.oth.4.p":"Самый простой вход, ничего не нужно устанавливать. Владение зависит от твоих 12 слов, а не от аккаунта в Telegram.","wallet.st.h":"В каком состоянии кошелёк","wallet.st.1.h":"Только Android","wallet.st.1.p":"Кошелёк — это APK с GitHub. Его нет в магазинах приложений, и приложения для iOS не существует.","wallet.st.2.h":"Готов к ревизии 6","wallet.st.2.p":"Версия 2.0.0 знает новый формат перевода и переходит на него на блоке 10 000. Более старая версия по-прежнему принимает YSR, но после этого блока не может отправлять.","wallet.st.3.h":"В планах: магазин приложений","wallet.st.3.p":"Планируется выпуск через Google Play. Даты нет.","wallet.st.4.h":"В планах: собственный узел","wallet.st.4.p":"Сегодня кошелёк читает данные с основного узла проекта. В планах — подключение к узлу, который ты держишь сам, чтобы никому не приходилось верить проекту на слово насчёт баланса.","mining.ways.p":"Каждый путь бесплатен и использует один и тот же кошелёк: со своими 12 словами ты везде попадаешь к одним и тем же YSR.","mining.tab.pc":"ПК","mining.tab.phone":"Телефон","mining.tab.cli":"Командная строка","mining.tab.rig":"Риг","mining.pc.h":"Node Core для Windows и Linux","mining.pc.p":"Full node, кошелёк и майнер в одной программе. Node Core сам проверяет каждый блок и майнит на твоём процессоре и на видеокартах NVIDIA, AMD и Intel. Версия 1.1.0, для Windows 10 и 11 и для 64-битного Linux.","mining.pc.s1":"Скачай установщик и запусти его.","mining.pc.s2":"Создай кошелёк и запиши 12 слов или перенеси свой кошелёк с их помощью.","mining.pc.s3":"В разделе Mining выбери solo или пул, укажи процессор или видеокарту и запусти.","mining.pc.win":"Скачать для Windows","mining.pc.deb":"Скачать для Linux (.deb)","mining.pc.more":"Также доступны: <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/download/node-core-v1.1.0/YSKAR-Node-Core-1.1.0-x86_64.AppImage' target='_blank' rel='noopener'>AppImage</a> для других дистрибутивов Linux и <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/tag/node-core-v1.1.0' target='_blank' rel='noopener'>описание релиза с контрольными суммами</a>.","mining.pc.note":"<strong>Установщик для Windows не подписан.</strong> Поэтому Windows один раз спросит: выбери «Подробнее», затем «Выполнить в любом случае». Сравни контрольную сумму с описанием релиза, если хочешь убедиться, что это именно опубликованный файл.","mining.pc.imgcap":"Node Core, обзор. Цифры на изображении приведены для примера.","mining.phone.h":"На телефоне","mining.phone.p":"Самый простой способ познакомиться с YSKAR. Телефон даёт мало хешрейта и находит блоки только в пуле. Серьёзный майнинг идёт на ПК и ригах.","mining.phone.s1":"Установи приложение для Android с GitHub или открой Mini App в Telegram.","mining.phone.s2":"Создай кошелёк и запиши 12 слов на бумаге.","mining.phone.s3":"Выбери пул и начни майнить.","mining.phone.apk":"Android-приложение с майнингом","mining.phone.tg":"Mini App в Telegram","mining.phone.f1":"Android-приложение","mining.phone.f1.v":"Продолжает майнить в фоне, даже при заблокированном экране, и показывает состояние в виджете на главном экране. Распространяется как APK, потому что магазины приложений не разрешают майнинг на устройстве.","mining.phone.f2":"Mini App","mining.phone.f2.v":"Ничего не нужно устанавливать. Работает внутри Telegram, пока он открыт. Твои монеты зависят от твоих 12 слов, а не от аккаунта в Telegram.","mining.phone.f3":"YSKAR Wallet","mining.phone.f3.v":"Приложение-кошелёк не майнит. Оно сделано для отправки, получения и подписи.","mining.cli.h":"Майнер для командной строки","mining.cli.p":"Для Windows, macOS и Linux. Майнеру нужен только адрес: ни ключа, ни кошелька, ни регистрации. Его можно запустить на компьютере, который ты не контролируешь.","mining.cli.f1":"Требования","mining.cli.f1.v":"Node.js 20 или новее, больше ничего устанавливать не нужно","mining.cli.f2":"Видеокарты","mining.cli.f2.v":"добавь <code>--gpu</code>. Используется <code>yskar-cuda</code> для NVIDIA и <code>yskar-opencl</code> для AMD и Intel","mining.cli.f3":"Solo","mining.cli.f3.v":"майни на собственном full node и убери <code>--mode pool</code>","mining.cli.link":"Полная инструкция по майнеру","mining.cli.c1":"скачать майнер и проверить этот компьютер","mining.cli.c2":"майнить в публичном пуле","mining.cli.c3":"или solo, на собственном узле","mining.cli.addr":"Замени <code>ysr1...</code> своим адресом. Награды приходят прямо на него.","mining.rig.h":"Майнинг-риги с HiveOS","mining.rig.p":"Готовый пакет для HiveOS: майнер для командной строки с программами для GPU, по одному майнеру на видеокарту.","mining.rig.dl":"Скачать пакет 1.1.0","mining.rig.doc":"Flight sheet и настройка","mining.rig.f1":"Карты","mining.rig.f1.v":"NVIDIA (CUDA), AMD и Intel (OpenCL)","mining.rig.f2":"Комиссия","mining.rig.f2.v":"в майнере её нет. Пул берёт собственную комиссию","mining.rig.f3":"Настройка","mining.rig.f3.v":"твой адрес и пул указываются во flight sheet. В инструкции показано каждое поле","mining.return":"<strong>Никто не может обещать тебе доход.</strong> То, как часто ты что-то получаешь, зависит от твоего хешрейта, от хешрейта всей сети и от случая. У YSR нет рыночной цены.","pools.p1":"В режиме solo ты ищешь один и оставляешь себе всю награду за найденный блок. В пуле многие ищут вместе, а награда делится по работе, которую выполнил каждый.","pools.p2":"Пул YSKAR — это не сервис с аккаунтами. Это узел, блоки которого платят каждому майнеру напрямую, в самом блоке. Оператор никогда не хранит чужие монеты, и порога выплаты нет.","pools.reported":"заявлено {r}","pools.c5":"Из последних {n}","pools.full":"заполнен","pools.cap":"Майнеры, места и хешрейт — это то, что каждый пул сообщает о себе сам. Доля в последних {n} блоках подсчитана по цепочке.","pools.f1":"Расчёт","pools.f1.v":"По долям за недавнее время (PPLNS). Если ты только начал, твоя часть первого блока будет небольшой.","pools.f2":"Места","pools.f2.v":"Блок может заплатить не более чем 64 адресам, поэтому в пуле 63 места плюс комиссия оператора. С ревизии 6 их будет 254.","pools.f3":"Комиссия","pools.f3.v":"Устанавливается оператором, от 0 до 5 %.","pools.f4":"Собственный пул","pools.f4.v":"Пулом может быть любой узел, без регистрации. <a class='ext' href='https://github.com/dabitlex/YSKAR/blob/main/docs/POOL.md' target='_blank' rel='noopener'>Как запустить свой</a>","calc.p":"Введи свой хешрейт. Оценка опирается на работу в последних блоках цепочки, а не на цифры, которые пулы сообщают о себе. Node Core и майнер показывают твой хешрейт во время работы.","calc.unit":"Единица","calc.mode":"Как ты майнишь","calc.pool":"В пуле","calc.solo":"Solo","calc.which":"Пул","calc.day":"В день, в среднем","calc.week":"За 7 дней","calc.month":"За 30 дней","calc.share":"Твоя доля в сети","calc.d.every":"В среднем один блок раз в","calc.d.chance":"Вероятность найти хотя бы один блок за 24 часа","calc.d.block":"За каждый найденный блок","calc.d.poolEvery":"Пул находит блок примерно раз в","calc.d.part":"Твоя часть каждого блока пула","calc.d.fee":"Комиссия пула, уже вычтена","calc.d.poolShare":"Доля пула в последних {n} блоках","calc.d.net":"Хешрейт сети по последним {n} блокам","calc.enter":"Введи хешрейт больше 0.","calc.note":"Оценка, а не обещание. Блоки находятся случайно, а сложность следует за всей сетью. Комиссии не учтены.","calc.halving":"До халвинга на блоке {b} осталось примерно {d} дн. Значения за 7 и 30 дней уже учитывают половинную награду после него.","calc.halving.1":"До халвинга на блоке {b} остался примерно {d} день. Значения за 7 и 30 дней уже учитывают половинную награду после него.","calc.every.min":"{n} минут","calc.every.min.few":"{n} минуты","calc.every.min.1":"{n} минуту","calc.every.hours":"{n} часов","calc.every.hours.1":"{n} час","calc.every.hours.few":"{n} часа","calc.every.hours.frac":"{n} часа","calc.every.days":"{n} дней","calc.every.days.1":"{n} день","calc.every.days.few":"{n} дня","calc.every.days.frac":"{n} дня","calc.every.years":"{n} лет","calc.every.years.1":"{n} год","calc.every.years.few":"{n} года","calc.every.years.frac":"{n} года","net.hashrate":"Хешрейт сети","net.difficulty":"Сложность","net.now":"Прямо сейчас","net.height":"Высота блока","net.fromChain":"работа последних 24 блоков, делённая на их время","net.everyBlock":"пересчитывается для каждого блока","net.blocktime":"Время блока, последние 50 блоков","net.target600":"цель: 600 с","net.mempool":"Ожидающие переводы","net.fromNode":"на основном узле","net.miners":"Активные майнеры","net.sessions":"Сессии майнинга","net.nodes":"Узлы на связи","net.reported":"заявлено, проверить нельзя","net.next.v6":"Ревизия 6 на блоке 10 000","net.next.halving":"Первый халвинг на блоке 12 000","net.hist.h":"История, прочитанная из блоков","net.hist.p":"Каждый блок цепочки, суммированный по дням в UTC. История полна до блока <span data-live='snapTip'></span>; цифры выше читаются в реальном времени.","net.range":"Период","net.range.all":"С блока 0","net.range.30":"30 дней","net.range.7":"7 дней","net.c.hash":"Хешрейт по дням","net.c.hash.capLog":"Работа блоков за день, делённая на их время. Логарифмическая шкала: каждая линия в десять раз больше той, что ниже.","net.c.hash.capLin":"Работа блоков за день, делённая на их время.","net.c.blocks":"Блоков в день","net.c.blocks.cap":"Только полные дни. При целевом времени блока в сутках 144 блока.","net.c.blocks.ref":"Цель: 144 блока в день","net.c.blocks.name":"блоки","net.c.finders":"Блоков в день, по тому, кто нашёл","net.c.finders.cap":"Только полные дни. Блоки пулов несут в цепочке имя пула; блок, который платит одному адресу, считается solo.","net.c.time":"Среднее время блока по дням","net.c.time.cap":"Секунды между блоками, в среднем за день.","net.c.time.ref":"Цель: 600 секунд","net.c.day":"День (UTC)","net.s.main":"YSKAR MAIN","net.s.gozero":"Gozero","net.s.solo":"Solo","net.find.h":"Кто находит блоки","net.find.p1":"В первые недели каждый блок находили в режиме solo. Сегодня почти все блоки приходят от двух пулов, и большинство — от одного.","net.find.p2":"Это важно. Оператор пула выбирает транзакции и родительский блок каждого блока, над которым работает пул, а тот, кто управляет большей частью хешрейта, может построить цепочку с наибольшей работой. Чем больше пулов и solo-майнеров, тем труднее управлять цепочкой.","net.find.link":"Пулы и как запустить свой","net.find.title":"Доля найденных блоков","net.find.last":"Последние {n} блоков","net.find.last1000":"1 000 блоков до блока {h}","net.find.allb":"Все блоки до блока {h}","net.find.cap":"Подсчитано по цепочке. Первая полоса следует за цепочкой в реальном времени, две другие заканчиваются там, где заканчивается встроенная в страницу история.","net.blocks.h":"Последние блоки","net.blocks.p":"Выбери блок, чтобы увидеть его заголовок, пересчитать его Proof of Work и прочитать его транзакции.","net.blocks.link":"Открыть explorer","net.blocks.title":"Сначала новые","net.b.height":"Высота","net.b.age":"Найден","net.b.by":"Нашёл","net.b.paid":"Выплачено","net.b.diff":"Сложность","net.b.solo":"solo","net.b.addr":"{n} адресов","net.b.addr.few":"{n} адреса","net.b.addr.1":"{n} адрес","net.src.h":"Откуда берутся цифры","net.src.p":"Не все цифры на этой странице имеют одинаковый вес.","net.src.1.h":"Из цепочки","net.src.1.p":"Высота, сложность, эмиссия и каждый график на этой странице. Хешрейт — это работа в последних блоках, делённая на время, которое они заняли. Всё это может пересчитать любой, у кого работает full node.","net.src.2.h":"Заявлено","net.src.2.p":"Активные майнеры, сессии, узлы и хешрейт, который пул сообщает о себе. Это данные со слов самих участников. Они показывают тенденцию, и никто не может их проверить.","net.src.3.h":"Зеркало","net.src.3.p":"Эта страница и explorer читают копию цепочки из базы данных, чтобы быстро загружаться. Зеркало проверяет каждый блок, который сохраняет, но это лишь удобство. Цепочка — это то, в чём сходятся full node.","net.src.4.h":"Seed-узлы","net.src.4.p":"Новый узел сначала обращается к <code>pool.yskar.app:8646</code> или <code>yskar-seed2.dynv6.net:8646</code>. Оба ведёт один и тот же оператор. После этого узлы обмениваются между собой адресами других узлов.","ex.q.label":"Поиск по цепочке","ex.q.go":"Найти","ex.try":"С чего начать:","ex.try.0":"блок 0","ex.try.burn":"сжигание в блоке 3 974","ex.try.or":"или","ex.try.zero":"адрес, с которого никто не может ничего потратить","ex.crumb":"Explorer","ex.msg.empty":"Введи высоту блока, хеш блока, ID транзакции или адрес.","ex.msg.badAddr":"В этом адресе опечатка: его контрольная сумма не сходится. Проверь его символ за символом.","ex.msg.addrShape":"Это не адрес YSKAR. Адреса начинаются с ysr1 и состоят из 42 символов.","ex.msg.tooHigh":"Блока {h} ещё нет. Цепочка сейчас на блоке {tip}.","ex.msg.notFound":"В цепочке нет ничего подходящего.","ex.msg.offlineHash":"Цепочка сейчас не отвечает, поэтому найти этот хеш нельзя. Попробуй ещё раз чуть позже.","ex.msg.searching":"Идёт поиск по цепочке.","ex.msg.badLink":"Эта ссылка не ведёт ни на блок, ни на транзакцию, ни на адрес.","ex.loading":"Чтение из цепочки.","ex.missing.h":"Цепочка сейчас не отвечает","ex.missing.p":"Explorer читает каждый блок, перевод и адрес из публичного API YSKAR, и этот запрос только что не удался. Он сам повторит попытку, как только цепочка ответит.","ex.missing.link":"Повторить сейчас","ex.none.block":"В цепочке нет блока {h}. Сейчас она на блоке {tip}.","ex.none.tx":"Транзакция с таким ID неизвестна: её нет ни в одном блоке, и она не ждёт блока. Если она была отправлена только что, эта страница сама проверит ещё раз.","ex.back":"Назад к последним блокам","ex.latest.h":"Последние блоки","ex.latest.snap":"Цепочка сейчас не отвечает. Это последние блоки ({n}) на момент последнего ответа.","ex.latest.live":"Прочитано из публичного API, обновляется каждые 45 секунд.","ex.older":"Показать более ранние блоки","ex.older.busy":"Чтение","ex.c.height":"Высота","ex.c.found":"Найден","ex.c.by":"Нашёл","ex.c.transfers":"Переводы","ex.c.size":"Размер","ex.c.hash":"Хеш блока","ex.solo":"Solo-майнер","ex.bytes":"{n} байт","ex.block.h":"Блок {h}","ex.prev":"Предыдущий блок","ex.next":"Следующий блок","ex.block.sumPool":"Найден {date}, {ago}, пулом {who}.","ex.block.sumSolo":"Найден {date}, {ago}, solo-майнером.","ex.block.sumGenesis":"Первый блок цепочки, датирован {date}. Его награда ушла на адрес, с которого никто не может ничего потратить.","ex.block.partial":"Цепочка сейчас не отвечает. Это заголовок блока в том виде, в каком он уже был у страницы, поэтому его Proof of Work всё равно можно проверить. Транзакции появятся, как только цепочка ответит.","ex.block.values":"Что записано в заголовке","ex.block.values.p":"Эти значения упакованы в 136 байт выше. Измени одно из них, и хеш перестанет подходить.","ex.f.hash":"Хеш блока","ex.f.prev":"Предыдущий блок","ex.f.prev.none":"Нет. Это первый блок.","ex.f.merkle":"Корень Меркла","ex.f.merkle.s":"Отпечаток транзакций этого блока","ex.f.state":"Корень состояния","ex.f.state.s":"Отпечаток всех балансов после этого блока","ex.f.diff":"Сложность","ex.f.diff.s":"В среднем требовалось около {n} попыток","ex.f.nonce":"Nonce и extranonce","ex.f.nonce.s":"Два счётчика, которые майнер перебирал, пока хеш не подошёл","ex.f.size":"Размер","ex.f.size.v":"{n} байт с {tx} транзакциями","ex.f.size.v.1":"{n} байт с {tx} транзакцией","ex.txs.h":"Транзакции в этом блоке","ex.txs.p":"Первая создаёт награду за блок. Все остальные — переводы, подписанные отправителем.","ex.tx.coinbase":"Награда за блок","ex.tx.transfer":"Перевод","ex.tx.other":"Транзакция типа {type}","ex.tx.new":"Вновь создано: {a}","ex.tx.newFees":"Вновь создано: {a}, комиссии: {f}","ex.tx.from":"От","ex.tx.to":"Кому","ex.tx.amount":"Сумма","ex.tx.fee":"Комиссия","ex.tx.memo":"Заметка","ex.tx.memoHex":"Заметка (байты)","ex.tx.nonce":"Счётчик отправителя","ex.tx.nonce.s":"Каждый перевод с адреса несёт следующий номер, поэтому ни один нельзя повторить","ex.tx.id":"ID транзакции","ex.tx.paid":"Выплачено прямо в блоке. Адресов: {n}. Пул никогда не держал эти монеты.","ex.tx.c.addr":"Адрес","ex.tx.c.amount":"Сумма в YSR","ex.tx.c.share":"Доля","ex.unspendable":"нельзя потратить","ex.txv.sum":"Подтверждено в блоке {h}, {date}.","ex.txv.block":"Блок","ex.txv.until":"Срок действия","ex.txv.until.none":"Срок не задан","ex.txv.until.h":"Блок {h}","ex.txv.size":"Размер","ex.txv.raw":"Байты в том виде, в каком они записаны в блоке","ex.txv.raw.p":"Узел проверяет именно эти байты: подпись, баланс отправителя и счётчик.","ex.txv.how":"Как устроен перевод","ex.addr.h":"Адрес","ex.addr.zero":"Ни у кого нет ключа от этого адреса. Всё, что сюда попадает, уже никогда нельзя будет потратить.","ex.addr.balance":"Баланс","ex.addr.sent":"Отправлено переводов","ex.addr.first":"Первое появление","ex.addr.last":"Последняя активность","ex.addr.blockN":"Блок {h}","ex.addr.solo":"Получено наград за блок","ex.addr.pool":"Получено выплат из пулов","ex.addr.hist":"Последние операции","ex.addr.more":"Последние записи: {n}.","ex.addr.none":"В цепочке пока нет записей об этом адресе. Адрес действителен, как только существует его ключ; цепочка узнаёт о нём с первым платежом.","ex.h.block":"Блок","ex.h.when":"Когда","ex.h.what":"Что","ex.h.with":"С кем","ex.h.amount":"Сумма","ex.h.fee":"Комиссия","ex.k.in":"Получено","ex.k.out":"Отправлено","ex.k.reward":"Награда за блок","ex.k.pool":"Выплата из пула","ex.copy.addr":"Копировать адрес","ex.copy.id":"Копировать ID","ex.block.sumPoolNoName":"Найден {date}, {ago}, пулом.","dev.node.h":"Запустить full node","dev.node.p":"Full node хранит собственную копию цепочки и сам проверяет каждый блок. Он ничего не принимает на веру: ни от других узлов, ни от этого сайта.","dev.node.link":"Что узел проверяет в каждом блоке","dev.node.c1":"Скачай исходный код и собери узел","dev.node.c2":"Запусти его: он подключается к seed-узлам, скачивает цепочку и проверяет каждый блок","dev.node.c3":"Майни на собственном узле, во втором терминале","dev.node.f1.k":"Что нужно","dev.node.f1.v":"Node.js 22.13 или новее и Git. Узел хранит цепочку с помощью модуля SQLite, встроенного в Node.js.","dev.node.f2.k":"Порты","dev.node.f2.v":"TCP 8646 для других узлов, 8645 для HTTP-интерфейса, которым пользуются майнеры и кошельки.","dev.node.f3.k":"Часы","dev.node.f3.v":"Следи, чтобы системные часы шли точно. Блок, датированный более чем на 120 секунд вперёд относительно часов твоего узла, отклоняется.","dev.node.f4.k":"Seed-узлы","dev.node.f4.v":"В узле для командной строки нет встроенного seed. Укажи оба seed-узла, как в команде выше.","dev.node.f5.k":"<code>--no-upstream</code>","dev.node.f5.v":"Должен быть в команде. Без него узел обменивался бы блоками ещё и с зеркалом проекта в базе данных, которое принимает блоки только от основного узла.","dev.node.core":"В Windows в PowerShell набирай <code>npm.cmd</code> вместо <code>npm</code>. Если окно тебе удобнее терминала, <a href=\"/node#core\">Node Core</a> запускает тот же full node в Windows и Linux.","dev.api.h":"Читать цепочку по HTTP","dev.api.p":"Публичный API отвечает на обычные GET-запросы в формате JSON. Выбери запрос и прочитай ответ.","dev.api.title":"Консоль API","dev.api.pick":"Запросы","dev.api.out":"Ответ","dev.api.run":"Отправить ещё раз","dev.api.curl":"Копировать как curl","dev.api.busy":"Ожидание ответа.","dev.api.ok":"{status} за {ms} мс, ответ в реальном времени от www.yskar.app.","dev.api.fail":"Запрос не удался ({why}). Показан последний ответ, полученный этой страницей, от {date}.","dev.api.e.summary":"Высота, сложность, хешрейт, эмиссия","dev.api.e.blocks":"Последние блоки, сначала новые","dev.api.e.block":"Один блок со всеми его транзакциями","dev.api.e.tx":"Одна транзакция по её ID","dev.api.e.account":"Баланс и история адреса","dev.api.e.search":"Что это за текст?","dev.api.e.fees":"Комиссия, которая нужна переводу прямо сейчас","dev.api.e.pools":"Пулы и цифры, которые они сообщают","dev.api.e.supply":"Добыто, нельзя потратить и в обращении","dev.api.e.circ":"Эмиссия в обращении в виде простого числа","dev.api.n1.h":"Только чтение, открытый доступ","dev.api.n1.p":"Без ключа и без аккаунта. Кросс-доменные запросы разрешены, поэтому веб-страница может обращаться к API напрямую.","dev.api.n2.h":"Твой собственный узел тоже отвечает","dev.api.n2.p":"Каждый full node отдаёт те же маршруты чтения на порту 8645. Направь свой код на <code>http://127.0.0.1:8645</code>, и ты не будешь зависеть ни от чьего сервера.","dev.api.n3.h":"Суммы — целые числа","dev.api.n3.p":"Суммы приходят в единицах: 1 YSR — это 100 000 000 единиц. Читай их как целые числа или строки и никогда как числа с плавающей запятой.","dev.docs.h":"Документы","dev.docs.p":"Написаны для тех, кто хочет проверить утверждения. Каждый документ ссылается на код, который он описывает.","dev.docs.v6":"Обязательная спецификация ревизии 6, действующей с блока 10 000.","dev.docs.fullnode":"Full node для командной строки: команды, параметры, HTTP-интерфейс, хранение данных и реорганизации.","dev.docs.p2p":"Протокол, на котором узлы общаются друг с другом.","dev.docs.fees":"Правила комиссий и то, как рассчитывается оценка комиссии.","dev.docs.pool":"Пулы: как присоединиться, как запустить свой и как устроен учёт.","dev.docs.ops":"Публичная инфраструктура: основной узел, HTTPS, зеркало и его настройки.","dev.repo.h":"Что где лежит","dev.repo.p":"В одном репозитории лежат код консенсуса, узел, майнер и тесты, которые их защищают.","dev.repo.core":"Консенсус: заголовок, сложность, транзакции, состояние, вывод ключей кошелька","dev.repo.fullnode":"Full node: цепочка, мемпул, интерфейс майнинга, API для чтения, командная строка","dev.repo.p2p":"Протокол между узлами","dev.repo.pool":"Учёт PPLNS и распределение награды за блок","dev.repo.node":"Сборка full node для командной строки","dev.repo.nodecore":"Node Core для Windows и Linux, с GPU-майнерами","dev.repo.miner":"Майнер для командной строки, без зависимостей","dev.repo.observer":"Наблюдатель: небольшой инструмент только для чтения, который скачивает цепочку и пересчитывает каждый блок","dev.repo.tests":"Тесты консенсуса, узла, P2P, пула и кошелька","dev.repo.docs":"Документация, перечисленная выше","dev.repo.c1":"Из корня репозитория: установи зависимости, запусти тесты, проверь типы","dev.sign.h":"Подписанные сообщения","dev.sign.p":"Кошелёк может доказать, что управляет адресом, не перемещая ни одной монеты. Всё программное обеспечение YSKAR подписывает и проверяет один и тот же текстовый формат.","dev.sign.1":"Подпись — это Ed25519 по исходным байтам UTF-8 всего сообщения; она проверяется по тому же правилу, что и в цепочке.","dev.sign.2":"Безопасным его делает первая строка: транзакция двоичная и никогда не начинается с этих слов, поэтому подписанное сообщение никогда не может быть засчитано как перевод.","dev.sign.3":"YSKAR Wallet и Node Core подписывают такие сообщения. YSKAR Lab использует их для входа без пароля.","dev.con.h":"Участвовать и сообщать","dev.con.1.h":"Изменения в коде","dev.con.1.p":"В <a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/blob/main/CONTRIBUTING.md\" target=\"_blank\" rel=\"noopener\">CONTRIBUTING.md</a> написано, какие проверки должны пройти перед push: проверка типов и полный набор тестов.","dev.con.2.h":"Идеи и предложения","dev.con.2.p":"Предложения по протоколу и программам открыто обсуждаются в <a class=\"ext\" href=\"https://lab.yskar.app\" target=\"_blank\" rel=\"noopener\">YSKAR Lab</a>. Вход через кошелёк.","dev.con.3.h":"Проблемы безопасности","dev.con.3.p":"Сообщай о них через issue на <a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/issues\" target=\"_blank\" rel=\"noopener\">github.com/dabitlex/YSKAR/issues</a>. Issues публичны: опиши, что ты видишь и как это воспроизвести, и никогда не публикуй свои 12 слов, PIN, файл кошелька или ключ.","ysr.now.blocks":"блоков","ysr.bar.circ":"В обращении","ysr.bar.burned":"Сожжено","ysr.bar.open":"Ещё не выпущено","ysr.bar.cap":"Доли от 21 000 000 YSR, которые вообще могут существовать.","ysr.sched.title":"Эмиссия по высоте блока","ysr.sched.series":"выпущено","ysr.sched.when.past":"уже добыт","ysr.sched.when.future":"примерно {date}, при 600 с на блок","ysr.t.all":"Показать все 37 эпох","ysr.t.less":"Показать первые 8 эпох","ysr.t.now":"сейчас","ysr.fees.h":"Комиссии","ysr.fees.p":"Перевод платит комиссию майнерам блока, в который он попадает. Правила задают только нижнюю границу. Выше неё цена следует за спросом на место в блоке.","ysr.fees.f1":"Нижняя граница по консенсусу","ysr.fees.f1.v":"1 единица за байт","ysr.fees.f2":"Нижняя граница для передачи","ysr.fees.f2.v":"10 единиц за байт. Это настройка узлов, а не правило консенсуса.","ysr.fees.f3":"Обычный перевод размером 168 байт","ysr.fees.f3.v":"как минимум, прямо сейчас","ysr.fees.f4":"Медленно, обычно, быстро","ysr.fees.f4.v":"Три уровня различаются только при заполненных блоках. В остальное время минимальной комиссии хватает для следующего блока.","ysr.fees.f5":"Наименьшая сумма","ysr.fees.f5.v":"100 единиц, то есть 0,000001 YSR","ysr.fees.f6":"Переводы, ожидающие блока","ysr.noprice.h":"Ни цены, ни обещаний","ysr.noprice.p1":"У YSR нет ни цены, ни рынка, и он не торгуется ни на одной бирже. Ничто на этом сайте не обещает, что это изменится, и никому не стоит майнить в расчёте на это.","ysr.noprice.p2":"Зато у YSR есть набор правил, которые может проверить каждый: фиксированный максимум, публичный график эмиссии и монеты, которые может переместить только ключ их владельца.","tech.header.h":"Блок начинается со 136 байт","tech.header.p1":"Заголовок называет предыдущий блок, фиксирует каждую транзакцию и каждый баланс после блока и содержит nonce, найденный майнером. Хеш блока — это SHA-256, применённый дважды ровно к этим байтам.","tech.header.p2":"Длина выбрана намеренно. SHA-256 работает блоками по 64 байта, и всё, кроме nonce, лежит в первых 128. Майнер вычисляет эту часть один раз на задание; каждая следующая попытка стоит двух шагов сжатия.","tech.pow.h":"Работа, которую может проверить каждый","tech.pow.p1":"Блок действителен, только если его хеш, прочитанный как число, не больше цели. Цель следует из сложности. Короткого пути нет: единственный способ найти такой хеш — перебирать nonce, а проверка результата требует двух вычислений хеша.","tech.pow.p2":"Одна единица сложности означает 65 536 ожидаемых попыток. При текущей сложности <span class='mono' data-live='difficulty'></span> сети нужно около <span data-live='attempts'></span> попыток на один блок.","tech.diff.h":"Сложность следует за сетью","tech.diff.p1":"Сложность пересчитывается для каждого блока по последним 45 блокам. Недавние блоки весят больше, чем старые, поэтому цепочка быстро реагирует, когда хешрейт приходит или уходит.","tech.diff.p2":"Каждый узел вычисляет один и тот же диапазон по одним и тем же блокам и отклоняет блок, в котором указана сложность вне этого диапазона. Используются только целые числа, поэтому два узла никогда не округлят по-разному.","tech.diff.chart":"Сложность с блока 1","tech.diff.cap":"Среднее по каждым 24 блокам до блока <span data-live='snapTip'></span>. Шкала логарифмическая: каждая линия в десять раз больше той, что ниже.","tech.diff.f1":"Окно","tech.diff.f1.v":"последние 45 блоков, самые новые — с наибольшим весом","tech.diff.f2":"Наибольший шаг","tech.diff.f2.v":"в 4 раза вверх или вниз за блок","tech.diff.f3":"Учитываемое время решения","tech.diff.f3.v":"от 1 до 3 600 секунд на блок","tech.diff.f4":"Аварийное правило","tech.diff.f4.v":"после 1 800 секунд без блока требование снижается пропорционально времени ожидания","tech.diff.f5":"Временные метки","tech.diff.f5.v":"позже медианы последних 11 блоков и не более чем на 120 секунд впереди часов узла","tech.acc.h":"Аккаунты и переводы","tech.acc.p1":"YSKAR хранит один баланс и один nonce на адрес. Перевод называет отправителя, получателя, сумму и комиссию и подписывается ключом отправителя. Без этого ключа никто не может переместить монеты.","tech.acc.p2":"Корень состояния в каждом заголовке фиксирует все балансы. Узел, который воспроизводит цепочку с блока 0, приходит к тем же балансам, что и любой другой узел, либо отклоняет блок.","tech.tx.title":"Перевод, 168 байт","tech.tx.p":"Плюс необязательная заметка до 32 байт. Размеры в байтах.","tech.tx.aria":"Поля перевода и их размеры в байтах","tech.tx.f1":"Версия и тип","tech.tx.f2":"Адрес отправителя","tech.tx.f3":"Адрес получателя","tech.tx.f4":"Сумма","tech.tx.f5":"Комиссия","tech.tx.f6":"Nonce отправителя","tech.tx.f7":"Высота истечения и длина заметки","tech.tx.f8":"Открытый ключ","tech.tx.f9":"Подпись","tech.acc.f1":"Действует один раз","tech.acc.f1.v":"Nonce должен равняться числу переводов, которые отправитель уже сделал, поэтому один и тот же перевод никогда не может быть применён дважды.","tech.acc.f2":"Привязан к этой сети","tech.acc.f2.v":"Подпись охватывает chain ID. Перевод, подписанный для YSKAR, недействителен где-либо ещё.","tech.acc.f3":"Срок действия","tech.acc.f3.v":"Отправитель может указать последнюю высоту блока. После неё перевод уже никогда не попадёт в блок.","tech.acc.f4":"Заметка","tech.acc.f4.v":"До 32 байт, публично хранятся в цепочке.","tech.acc.f5":"Минимальная комиссия","tech.acc.f5.v":"1 единица за байт по консенсусу. Узлы передают дальше от 10 единиц за байт. Комиссии достаются майнерам блока.","tech.acc.f6":"Обычный перевод стоит","tech.acc.f6.v":"прямо сейчас как минимум","tech.key.aria":"От 12 слов к адресу","tech.key.1":"Seed-слова","tech.key.2":"Путь вывода ключа","tech.key.3":"Пара ключей","tech.key.4":"Адрес","tech.key.p":"Кошелёк — это 12 или 24 слова (BIP39). Ключ выводится из них на устройстве (SLIP-0010), а адрес — это первые 20 байт хеша SHA-256 открытого ключа, записанные в bech32m. Слова никогда не покидают устройство, которое их создало.","tech.nodes.h":"Каждый узел проверяет каждый блок","tech.nodes.p1":"Full node хранит всю цепочку и принимает блок только после полной проверки, независимо от того, пришёл ли блок от другого узла или от собственного майнера. Проверки идут в таком порядке.","tech.nodes.link":"Запустить full node","tech.check.1":"Версия, не более 2 000 транзакций, ровно одна транзакция с наградой на первом месте и корень транзакций.","tech.check.2":"Хеш заголовка, применённый дважды, не больше цели для указанной сложности.","tech.check.3":"Высота равна высоте родительского блока плюс один, а предыдущий хеш — это хеш родительского блока.","tech.check.4":"Позже медианы последних 11 блоков, не раньше родительского блока и не более чем на 120 секунд впереди часов узла.","tech.check.5":"Указанная сложность лежит в диапазоне, который следует из предыдущих блоков.","tech.check.6":"Подпись, отправитель, nonce, баланс, комиссия и срок действия каждого перевода. Транзакция с наградой выплачивает ровно награду за блок плюс комиссии.","tech.check.7":"Корень по всем аккаунтам после блока равен корню состояния в заголовке.","tech.nodes.chain.h":"Какая цепочка считается","tech.nodes.chain.p":"Действительная цепочка с наибольшей накопленной работой, где работа блока — это его сложность. Узел хранит конкурирующие блоки и переключается, когда у другой ветви работы больше.","tech.nodes.pool.h":"Пулы без хранения средств","tech.nodes.pool.p":"Транзакция с наградой в блоке может платить до 64 адресам. Учёт пула становится этой транзакцией, поэтому цепочка платит каждому майнеру напрямую, а оператор никогда не держит чужие монеты. <a href='/mining#pools'>Как работают пулы</a>","tech.rev.h":"Правила меняются на определённой высоте блока","tech.rev.p":"Изменение правил записывается в код вместе с высотой, с которой оно начинает действовать. Все узлы переключаются на одном и том же блоке, а каждый блок ниже этой высоты сохраняет свои правила, байт в байт.","tech.rev.c1":"Ревизия","tech.rev.c2":"С блока","tech.rev.c3":"Изменение","tech.rev.c4":"Статус","tech.rev.2":"Транзакция с наградой может платить нескольким адресам. На этом построены пулы.","tech.rev.3":"Минимальная комиссия за байт заменяет фиксированную комиссию, и вводится наименьшая сумма.","tech.rev.4":"Поле сложности может содержать значения любой величины.","tech.rev.5":"Более строгие правила для временных меток, кодирования блоков и транзакции с наградой.","tech.rev.6":"Общие аккаунты, блокировки по времени и по хешу, пакетные платежи, новое дерево состояния и более высокие лимиты.","tech.rev.note":"Ревизии со 2 по 5 исправляли и ужесточали правила. Ревизия 6 — первая, которая добавляет возможности, и первая, за которой старые узлы следовать не могут.","tech.v6.h":"Ревизия 6","tech.v6.p":"Следующее изменение правил начинается с блока 10 000. Сообщество выбрало эту высоту голосованием 25 октября 2026 года. Оно меняет запись аккаунта, формат адреса и формат транзакции, чтобы аккаунты могли больше, чем просто хранить баланс.","tech.v6.count":"Блок 10 000","tech.v6.spec":"Читать спецификацию ревизии 6","tech.v6.1.h":"Общие аккаунты","tech.v6.1.p":"Аккаунты, для расходования с которых нужно несколько подписей, например 2 из 3, до 16 ключей. Для общих средств и более надёжных сбережений.","tech.v6.2.h":"Блокировки по времени","tech.v6.2.p":"YSR, которые можно потратить только начиная с выбранной высоты блока.","tech.v6.3.h":"Хеш-блокировки","tech.v6.3.p":"Платёж высвобождается только в обмен на секрет и возвращается отправителю после заданной высоты. Две стороны могут обмениваться, не доверяя друг другу.","tech.v6.4.h":"Пакетные платежи","tech.v6.4.p":"Одна транзакция платит сразу до 1 000 получателям.","tech.v6.5.h":"Больше места в блоке","tech.v6.5.p":"До 5 000 транзакций в блоке вместо 2 000, а блок пула может платить до 255 адресам вместо 64.","tech.v6.6.h":"Фундамент на будущее","tech.v6.6.p":"Дерево состояния, рассчитанное на многие тысячи аккаунтов, адреса с версией и идентификатор форка в каждой подписи.","tech.v6.same.h":"Что остаётся прежним","tech.v6.same.1":"21 миллион YSR и график халвингов","tech.v6.same.2":"10-минутные блоки, SHA-256 и правила сложности","tech.v6.same.3":"Каждый адрес, каждый ключ и каждый баланс","tech.v6.do.h":"Что нужно сделать","tech.v6.do.1":"Обнови кошелёк и узел до блока 10 000","tech.v6.do.2":"Майнерам, GPU-майнерам и пакету HiveOS обновление не требуется","tech.v6.do.3":"Устаревший кошелёк по-прежнему получает YSR. Отправлять он не сможет, пока его не обновят","tech.lim.h":"Известные ограничения","tech.lim.p":"От чего система сегодня не защищает. Список взят из собственного документа проекта о безопасности.","tech.lim.link":"Полная модель безопасности","tech.lim.1.h":"Небольшая сеть","tech.lim.1.p":"В сети два seed-узла, и оба ведёт один и тот же оператор. Proof of Work защищает цепочку лишь до тех пор, пока ни одна сторона не контролирует большую часть хешрейта, а хешрейтом, который майнит через один пул, управляет оператор этого пула.","tech.lim.2.h":"Нет контрольных точек","tech.lim.2.p":"Узел переключается на любую действительную цепочку с большей работой, как бы далеко в прошлом она ни ответвлялась. Считай перевод тем более окончательным, чем больше блоков построено поверх него.","tech.lim.3.h":"Источник данных explorer","tech.lim.3.p":"Explorer и приложения читают данные из зеркала — копии цепочки в базе данных, которая ведётся ради скорости. Это удобство, а не источник истины: цепочка — это то, в чём сходятся full node.","tech.lim.4.h":"Места в пуле","tech.lim.4.p":"В пуле не больше 64 мест, 63, если он берёт комиссию; с ревизии 6 это 255 и 254. Чтобы открыть сессию, нужен только действительный адрес, поэтому места можно занять без особых затрат.","tech.lim.5.h":"Открытые интерфейсы","tech.lim.5.p":"HTTP-интерфейс узла не ограничивает число запросов от одного клиента. На публичном узле это должен делать обратный прокси.","tech.docs.1":"Спецификация протокола: форматы, хеширование, сложность, правила валидности и тестовые векторы.","tech.docs.3":"Что обеспечивают криптография и консенсус, чему приходится доверять и известные ограничения.","miner.title":"Поищи nonce самостоятельно","miner.state":"Работает в твоём браузере","miner.intro":"Твой браузер берёт заголовок последнего блока и перебирает nonce для более лёгкой цели. Настоящая цель находится далеко за пределами того, чего может достичь браузер.","miner.bits":"Нулевые биты, с которых должен начинаться хеш","miner.odds":"Бит: {b}. Подходит примерно 1 хеш из {n}","miner.start":"Начать поиск","miner.stop":"Стоп","miner.attempts":"Попытки","miner.speed":"Скорость","miner.time":"Время","miner.nonce":"Найденный nonce","miner.hash":"Последний проверенный хеш","miner.hashFound":"Найденный хеш","miner.target":"Цель этой демонстрации","miner.found":"Найдено. Попыток: {n}.","miner.none":"Попыток: {n}, хеша ниже цели не нашлось. Начни заново или выбери меньше нулевых бит.","miner.stopped":"Остановлено. Попыток: {n}.","miner.real":"При {r} этот браузер искал бы настоящий блок при сегодняшней сложности в среднем примерно {t}.","field.version":"Версия","field.version.d":"Версия заголовка. Сегодня она равна 1, а с ревизией консенсуса 6 станет равна 6.","field.height":"Высота","field.height.d":"Номер этого блока, считая с блока 0.","field.prev":"Предыдущий хеш","field.prev.d":"Хеш предыдущего блока. Он связывает блоки в цепочку: изменение старого блока изменило бы каждый хеш после него.","field.merkle":"Корень транзакций","field.merkle.d":"Один хеш по всем транзакциям блока. Изменение хотя бы одного байта в любой из них меняет его.","field.state":"Корень состояния","field.state.d":"Один хеш по всем балансам и nonce после этого блока. Каждый узел вычисляет его сам и сравнивает.","field.time":"Временная метка","field.time.d":"Когда майнер собрал блок. Это время должно быть позже медианы последних 11 блоков.","field.diff":"Сложность","field.diff.d":"Насколько трудным должен был быть этот блок. Цель следует из неё: 2^240, делённое на сложность.","field.count":"Число транзакций","field.count.d":"Сколько транзакций содержит блок, включая ту, что выплачивает награду.","field.extra":"Extranonce","field.extra.d":"Значение, которое узел выдаёт каждому майнеру, чтобы два майнера никогда не перебирали одни и те же заголовки.","field.nonce":"Nonce","field.nonce.d":"Число, которое майнер менял, пока хеш не оказался ниже цели. Между двумя попытками больше ничего не меняется.","proof.fixedBlock":"Закреплён в цепочке","proof.block":"Блок {h}","proof.found":"найден {ago}","proof.fixed":"Без изменений с 9 сент. 2026","proof.cap":"Заголовок блока: 136 байт в десяти полях.","proof.bytesLabel":"136 байт заголовка блока {h} в шестнадцатеричном виде","proof.range":"байты с {a} по {b}","proof.first":"SHA-256 от 136 байт","proof.hash":"SHA-256, применённый дважды: хеш блока","proof.target":"Цель при сложности {d}","proof.valid":"Действителен. Хеш ниже цели.","proof.invalid":"Недействителен. Хеш выше цели.","proof.time":"Вычислено в твоём браузере за {ms} мс.","proof.again":"Проверить ещё раз","proof.genesis":"Проверить блок 0","proof.latest":"Проверить последний блок","proof.open":"Открыть этот блок в explorer","check.1":"Структура","check.2":"Proof of Work","check.3":"Место в цепочке","check.4":"Временная метка","check.5":"Сложность","check.6":"Каждая транзакция","check.7":"Корень состояния","chart.asTable":"Показать значения в виде таблицы","chart.total":"всего","chart.height":"До блока","n.2000":"2 000","n.4000":"4 000","n.6000":"6 000","n.7000":"7 000","n.10000":"10 000","rev.active":"действует с {date}","rev.set":"назначена, осталось блоков: {n}","ms.done":"действует","home.how.1.h":"Майнеры ищут","home.how.1.p":"Телефоны, ПК и видеокарты снова и снова хешируют заголовок блока, каждый раз с другим nonce. Хеш ниже цели делает блок действительным.","home.how.2.h":"Узлы проверяют","home.how.2.p":"Каждый full node пересчитывает работу, подписи и все балансы, начиная с блока 0. Блок, нарушающий правило, отклоняется, кто бы его ни отправил.","home.how.3.h":"Блок платит","home.how.3.p":"Награду выплачивает сам блок: только тому, кто его нашёл, или с разделом между майнерами пула, прямо на их адреса. Пул никогда не держит чужие монеты.","dev.api.down":"Запрос не удался ({why}). API сейчас отсюда не отвечает."};window.YSKAR_TEXTE_DA&&window.YSKAR_TEXTE_DA("ru");
